Object.assign(window.TEM8_DICTIONARY, {"blessing":{"media":{"uk":"media/uk/blessing__gb_1.mp3","us":"media/us/blessing__us_1.mp3"},"oxford":{"phon":"ˈblesɪŋ","pos":"noun","senses":[{"en":"God’s help and protection, or a prayer asking for this","cn":"上帝的恩宠；祝福；祝颂","g":"[usually singular]","lab":"North American English","ex":{"en":"to pray for God’s blessing","cn":"祈求上帝降福"}},{"en":"approval of or permission for something","cn":"赞同；许可","g":"[usually singular]","ex":{"en":"The government gave its blessing to the new plans.","cn":"政府已批准这些新计划。"}},{"en":"something that is good or helpful","cn":"好事；有益之事","ex":{"en":"Lack of traffic is one of the blessings of country life.","cn":"往来车辆少是乡村生活的一大好处。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"幸事；福气；好事；福祉","en":"A blessing is something good that you are grateful for.","ex":{"en":"Rivers are a blessing for an agricultural country.","cn":"河流对于一个农业国家来说是一种恩赐。"}},{"pos":"N-COUNT 可数名词","cn":"支持；赞同；准许","en":"If something is done with someone's blessing, it is done with their approval and support.","ex":{"en":"With the blessing of the White House, a group of Democrats in Congress is meeting to find additional budget cuts","cn":"在白宫的支持下，一群民主党国会议员将开会寻求进一步缩减预算。"}},{"pos":"N-COUNT 可数名词","cn":"祈福；祷告；祈祷","en":"A blessing is a prayer asking God to look kindly upon the people who are present or the event that is taking place."},{"pos":"PHRASE 短语","cn":"不要身在福中不知福；想想自己有多幸运","en":"If you tell someone to count their blessings, you are saying that they should think about how lucky they are instead of complaining.","ex":{"en":"Some would argue this was no burden in fact, and that she should count her blessings.","cn":"有些人可能会说这事实上算不上什么负担，她应该想想自己有多幸运。"}},{"pos":"PHRASE 短语","cn":"因祸得福；坏事变好事；祸中有福","en":"If you say that something is a blessing in disguise, you mean that it causes problems and difficulties at first but later you realize that it was the best thing that could have happened.","ex":{"en":"The failure to conclude the trade talks last December could prove a blessing in disguise.","cn":"去年12月份贸易谈判中止可能因祸得福。"}},{"pos":"PHRASE 短语","cn":"祸福兼有；有利有弊","en":"If you say that a situation is a mixed blessing, you mean that it has disadvantages as well as advantages.","ex":{"en":"For ordinary Italians, Sunday's news probably amounts to a mixed blessing.","cn":"对普通的意大利人民来说，星期天的新闻可以说是悲喜交加。"}}]},"examples":[{"en":"Lack of traffic is one of the blessings of country life.","cn":"往来车辆少是乡村生活的一大好处。"},{"en":"He went with his parents' blessing.","cn":"他是得到父母的同意去的。"}]},"blank":{"media":{"uk":"media/uk/blank__gb_1.mp3","us":"media/us/blank__us_1.mp3"},"oxford":{"phon":"blæŋk","pos":"adjective","senses":[{"en":"empty, with nothing written, printed or recorded on it","cn":"空白的","ex":{"en":"Sign your name in the blank space below.","cn":"把名字签在下面的空白处。"}},{"en":"empty; with no pictures, marks or decoration","cn":"空的；无图画（或标记、装饰）的","ex":{"en":"blank whitewashed walls","cn":"光秃秃的白灰墙"}},{"en":"showing no feeling, understanding or interest","cn":"没表情的；不理解的；不感兴趣的","ex":{"en":"She stared at me with a blank expression on her face.","cn":"她一脸木然地盯着我。"}},{"en":"complete and total","cn":"完全的；彻底的","g":"[only before noun]","ex":{"en":"a blank refusal/denial","cn":"断然拒绝／否认"}},{"en":"an empty space on a printed form or document for you to write answers, information, etc. in","cn":"（文件等的）空白处，空格","g":"[countable]","ex":{"en":"Please fill in the blanks.","cn":"请在空白处填写。"},"pos":"noun"},{"en":"a state of not being able to remember anything","cn":"（记忆中的）空白，遗忘","g":"[singular]","ex":{"en":"My mind was a blank and I couldn't remember her name.","cn":"我脑子里一片空白，记不起她的名字了。"},"pos":"noun"},{"en":"a cartridge in a gun that contains an explosive but no bullet","cn":"空弹","g":"[countable]","ex":{"en":"The troops fired blanks in the air.","cn":"部队向天放空弹。"},"pos":"noun"},{"en":"to ignore somebody completely","cn":"毫不理睬（某人）","g":"[transitive]","lab":"British English, informal，，","ex":{"en":"I saw her on the bus this morning, but she totally blanked me.","cn":"我今天早晨在公共汽车上见到她，但她连一眼都没瞧我。"},"pos":"verb"},{"en":"to be suddenly unable to remember or think of something","cn":"突然忘掉；突然思路模糊","g":"[intransitive]","lab":"North American English","ex":{"en":"I knew the answer, but I totally blanked during the test.","cn":"我本来知道答案，但考试时我什么都忘了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"空白的；空的","en":"Something that is blank has nothing on it.","ex":{"en":"We could put some of the pictures over on that blank wall over there","cn":"我们可以把一些图画贴在那边的空白墙壁上。"}},{"pos":"N-COUNT 可数名词","cn":"空白处；空格","en":"A blank is a space which is left in a piece of writing or on a printed form for you to fill in particular information.","ex":{"en":"Put a word in each blank to complete the sentence.","cn":"每个空格填上一个单词，把句子补充完整。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"茫然的；漠然的；毫无表情的","en":"If you look blank, your face shows no feeling, understanding, or interest.","ex":{"en":"Abbot looked blank. 'I don't quite follow, sir.'","cn":"阿博特一脸茫然。“我没听明白，先生。”"}},{"pos":"N-SING 单数名词","cn":"（头脑或记忆）一片空白","en":"If your mind or memory is a blank, you cannot think of anything or remember anything.","ex":{"en":"I'm sorry, but my mind is a blank","cn":"对不起，我脑子里一片空白。"}},{"pos":"N-COUNT 可数名词","cn":"空包弹","en":"Blanks are gun cartridges which contain explosive but do not contain a bullet, so that they cause no harm when the gun is fired.","ex":{"en":"...a starter pistol which only fires blanks.","cn":"只发射空包弹的发令枪"}},{"pos":"PHRASE 短语","cn":"一无所获；扑空","en":"If you draw a blank when you are looking for someone or something, you do not succeed in finding them.","ex":{"en":"They drew a blank in their search for the driver.","cn":"他们四处寻找那个司机，但一无所获。"}},{"pos":"PHRASE 短语","cn":"（脑子）突然一片空白","en":"If your mind goes blank, you are suddenly unable to think of anything appropriate to say, for example in reply to a question.","ex":{"en":"My mind went totally blank.","cn":"我的脑子突然一片空白。"}},{"pos":"","cn":"","en":"相关词组：blank out"}]},"examples":[{"en":"I saw her on the bus this morning, but she totally blanked me.","cn":"我今天早晨在公共汽车上见到她，但她连一眼都没瞧我。"},{"en":"Steve looked blank and said he had no idea what I was talking about.","cn":"史蒂夫显得很迷惑，说他不知道我在说什么。"}]},"blackboard":{"oxford":{"phon":"ˈblækbɔːd","pos":"noun","senses":[{"en":"a large board with a smooth black or dark green surface that teachers write on with a piece of chalk","cn":"黑板","ex":{"en":"to write on the blackboard","cn":"在黑板上写字"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"黑板","en":"A blackboard is a dark-coloured board that you can write on with chalk. Blackboards are often used by teachers in the classroom."}]},"media":{"uk":"media/uk/blackboard__gb_1.mp3","us":"media/us/blackboard__us_1.mp3","img":["media/ldoce/img/blackboard.jpg"]},"examples":[{"en":"to write on the blackboard","cn":"在黑板上写字"}]},"blankness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used about something that has nothing inside","cn":""},{"en":"used about a computer screen or a piece of paper that has no writing or pictures on it, or a CD, DVD etc with nothing recorded on it","cn":""}]},"examples":[{"en":"Leave the last page blank .","cn":"","src":"ld"},{"en":"Zoe looked at me with a blank expression.","cn":"","src":"ld"}],"media":{"uk":"media/uk/blankness__gb_1.mp3","us":"media/us/blankness__us_1.mp3"},"oxford":{"phon":"ˈblæŋknəs","pos":"noun","senses":[{"en":"a total lack of feeling, understanding or interest","cn":"没表情的；不理解的；不感兴趣的","ex":{"en":"emotional blankness","cn":"情感空白"}},{"en":"the quality of being empty, with no pictures, marks or decoration","cn":"空的；无图画（或标记、装饰）的","ex":{"en":"the blankness of a nearly white winter sky","cn":"冬日近乎白色的天空一片空白"}}]}},"block":{"media":{"img":["media/pic/homes_comp.jpg","media/thumb/flat.jpg","media/ldoce/img/block_ice.jpg"],"uk":"media/uk/block__gb_1.mp3","us":"media/us/block__us_1.mp3"},"oxford":{"phon":"blɒk","pos":"noun","senses":[{"en":"a large piece of a solid material that is square or rectangular in shape and usually has flat sides","cn":"（方形或长方形）大块；立方体；长方体","g":"[countable]","sc":"solid material","ex":{"en":"The houses are made of concrete blocks with tin roofs.","cn":"这些房子用混凝土砌块建造，带铁皮屋顶。"}},{"en":"a tall building that contains flats or offices; buildings that form part of a school, hospital, etc. which are used for a particular purpose","cn":"（公寓、办公、教学、医院等）大楼；（成组建筑中的）一栋楼房","g":"[countable]","lab":"British English","sc":"building","ex":{"en":"a block of flats","cn":"公寓大楼"}},{"en":"the length of one side of a piece of land or group of buildings, from the place where one street crosses it to the next","cn":"（两条街道之间的）一段街区","g":"[countable]","lab":"North American English","sc":"streets","ex":{"en":"His apartment is three blocks away from the police station.","cn":"他住在和警察局相隔三个街区的公寓里。"}},{"en":"a group of buildings with streets on all sides","cn":"街道围成的楼群；街区","g":"[countable]","lab":"North American English","sc":"streets","ex":{"en":"She took the dog for a walk around the block.","cn":"她带着狗绕街区散步。"}},{"en":"a large area of land","cn":"一大片土地","g":"[countable]","lab":"especially North American English","sc":"area of land"},{"en":"an area of land for building a house on","cn":"房基地；宅基地","g":"[countable]","lab":"Australian English","sc":"area of land"},{"en":"a quantity of something or an amount of time that is considered as a single unit","cn":"（东西的）一批，一组；（时间的）一段","g":"[countable]","lab":"British English","sc":"amount","ex":{"en":"a block of shares","cn":"一大宗股份"}},{"en":"something that makes movement or progress difficult or impossible","cn":"障碍物；阻碍；妨害","g":"[countable, usually singular]","sc":"that stops progress","ex":{"en":"Lack of training acts as a block to progress in a career.","cn":"缺乏训练会妨碍事业的发展。"}},{"en":"a movement that stops another player from going forward","cn":"阻挡；拦截","g":"[countable]","sc":"in sport"},{"en":"the two blocks on the ground that runners push their feet against at the beginning of a race","cn":"起跑器","g":"[plural]","sc":"in sport"},{"en":"(in the past) the piece of wood on which a person’s head was cut off as a punishment","cn":"（旧时斩首用的）垫头木","g":"[singular]","sc":"for punishment"},{"en":"to stop something from moving or flowing through a pipe, a passage, a road, etc. by putting something in it or across it","cn":"堵塞；阻塞","ex":{"en":"After today's heavy snow, many roads are still blocked.","cn":"今天下过大雪，很多道路仍然堵塞。"},"pos":"verb"},{"en":"to stop somebody from going somewhere or seeing something by standing in front of them or in their way","cn":"堵住（某人的路等）；挡住（某人的视线等）","ex":{"en":"One of the guards moved to block her path.","cn":"一名守卫走过去挡住她的路。"},"pos":"verb"},{"en":"to prevent something from happening, developing or making progress","cn":"妨碍；阻碍","ex":{"en":"The proposed merger has been blocked by the government.","cn":"建议中的合并计划遇到了政府的阻力。"},"pos":"verb"},{"en":"to stop a ball, hit, etc. from reaching somewhere by moving in front of it","cn":"拦截，挡住（球、打击等）","ex":{"en":"His shot was blocked by the goalie.","cn":"他起脚射门，球被守门员拦住了。"},"pos":"verb"},{"en":"to stop a mobile/cell phone from being used, for example after it has been stolen","cn":"锁定，禁用（被盗的手机等）","ex":{"en":"Police have accused mobile networks of failing to block stolen phones.","cn":"警方指责移动网络未能阻止被盗手机。"},"pos":"verb"},{"en":"to prevent someone from contacting you on social media","cn":"拉黑，屏蔽（在社交媒体上阻止某人与你联系）","ex":{"en":"There are many reasons to block someone online.","cn":"在线阻止某人的原因有很多。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大楼；大厦","en":"A block of flats or offices is a large building containing them.","ex":{"en":"...blocks of council flats.","cn":"一栋栋市政公寓大楼"}},{"pos":"N-COUNT 可数名词","cn":"街区","en":"A block in a town is an area of land with streets on all its sides.","ex":{"en":"She walked four blocks down High Street","cn":"她沿着商业大街走了4个街区。"}},{"pos":"N-COUNT 可数名词","cn":"（长方形）块，大块","en":"A block of a substance is a large rectangular piece of it.","ex":{"en":"...a block of ice.","cn":"一大块冰"}},{"pos":"VERB 动词","cn":"阻塞，堵塞（道路、管道等）","en":"To block a road, channel, or pipe means to put an object across it or in it so that nothing can pass through it or along it.","ex":{"en":"Some students today blocked a highway that cuts through the center of the city","cn":"今天一些学生堵塞了一条贯穿市中心的公路。"}},{"pos":"VERB 动词","cn":"挡住，遮住（视线）","en":"If something blocks your view, it prevents you from seeing something because it is between you and that thing.","ex":{"en":"...a row of spruce trees that blocked his view of the long north slope of the mountain.","cn":"一排云杉挡住了他的视线，使他看不到这座山绵长的北坡"}},{"pos":"VERB 动词","cn":"堵住，阻挡，挡住（去路）","en":"If you block someone's way, you prevent them from going somewhere or entering a place by standing in front of them.","ex":{"en":"I started to move round him, but he blocked my way","cn":"我准备绕过他，但他挡住了我。"}},{"pos":"VERB 动词","cn":"阻挠；阻止；妨碍","en":"If you block something that is being arranged, you prevent it from being done.","ex":{"en":"For years the country has tried to block imports of various cheap foreign products","cn":"多年来，这个国家一直竭力阻挠各种廉价外国产品的进口。"}},{"pos":"VERB 动词","cn":"（体育运动中）拦截，阻截（进球、对手等）","en":"In some sports, if a player blocks a shot or kick, they stop the ball reaching its target. If one player blocks another, the first stops the second from reaching or moving with the ball.","ex":{"en":"In the final seconds, Gunn goalie Kevin Cantwell blocked two shots.","cn":"在最后的几秒钟，甘恩队的守门员凯文·坎特维尔扑出了两次射门。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指按特定顺序同时售出的）大量，大批，大套（票、股票等）","en":"A block of something such as tickets or shares is a large quantity of them, especially when they are all sold at the same time and are in a particular sequence or order.","ex":{"en":"Those booking a block of seats get them at reduced rates.","cn":"团体订座可享受折扣价。"}},{"pos":"N-COUNT 可数名词","cn":"（短时间的）思维停滞，思维中断","en":"If you have a mental block or a block, you are temporarily unable to do something that you can normally do which involves using, thinking about, or remembering something."},{"pos":"See also:","cn":"","en":"→see: ;"},{"pos":"PHRASE 短语","cn":"冒着败坏名声的风险；拿名誉（或地位）做赌注","en":"If someone lays their head on the block, or puts their head on the block, they are risking their reputation or position by taking a particular course of action.","ex":{"en":"The Chancellor, by his unusual statement, has put his head on the block.","cn":"这位总理冒着丢乌纱帽的风险发表了一份非同寻常的声明。"}},{"pos":"","cn":"","en":"相关词组：block in block off block out block up"}]},"examples":[{"en":"Over the years she had tried to block out that part of her life.","cn":"多年来她努力想把她生命中的那一段经历从记忆中抹去。"},{"en":"The three-hour class is divided into four blocks of 45 minutes each.","cn":"三小时的课分成四节，每节 45 分钟。"}]},"blunt":{"media":{"uk":"media/uk/blunt__gb_1.mp3","us":"media/us/blunt__us_1.mp3"},"oxford":{"phon":"blʌnt","pos":"adjective","senses":[{"en":"without a sharp edge or point","cn":"不锋利的；钝的","ex":{"en":"a blunt knife","cn":"钝刀子"}},{"en":"very direct; saying exactly what you think without trying to be polite","cn":"嘴直的；直言的","ex":{"en":"She has a reputation for blunt speaking.","cn":"她说话出了名地直截了当。"}},{"en":"to make something weaker or less effective","cn":"削弱；降低；使降低效果","ex":{"en":"Age hadn't blunted his passion for adventure.","cn":"岁月没有冲淡他的冒险激情。"},"pos":"verb"},{"en":"to make a point or an edge less sharp","cn":"使（尖端、刃）变钝","pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"直率的；不客气的；直言不讳的","en":"If you are blunt, you say exactly what you think without trying to be polite.","ex":{"en":"She is blunt about her personal life","cn":"她对自己的私生活直言不讳。"}},{"pos":"ADJ 形容词","cn":"（物体）钝的，不锋利的，不尖的","en":"A blunt object has a rounded or flat end rather than a sharp one.","ex":{"en":"One of them had been struck 13 times over the head with a blunt object.","cn":"他们中有一个人的头部被钝器击打13次。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（刀子或刀片）钝的，不锋利的","en":"A blunt knife or blade is no longer sharp and does not cut well."},{"pos":"VERB 动词","cn":"使（情感、感觉、需求）减弱；使迟钝","en":"If something blunts an emotion, a feeling or a need, it weakens it.","ex":{"en":"The constant repetition of violence has blunted the human response to it","cn":"反复出现的暴力事件使人们的反应都变得麻木了。"}}]},"examples":[{"en":"To be blunt, your work is appalling.","cn":"坦率地说，你的活干得糟透了。"},{"en":"Age hadn't blunted his passion for adventure.","cn":"岁月没有冲淡他的冒险激情。"}]},"blanks":{"lemma":"blank","media":{"uk":"media/uk/blank__gb_1.mp3","us":"media/us/blank__us_1.mp3"}},"blurred":{"media":{"uk":"media/uk/blurred__gb_1.mp3","us":"media/us/blurred__us_1.mp3"},"oxford":{"phon":"blɜːd","pos":"adjective","senses":[{"en":"not clear; without a clear outline or shape","cn":"模糊不清的","ex":{"en":"She suffered from dizziness and blurred vision.","cn":"她饱受头晕目眩之苦。"}},{"en":"difficult to remember clearly","cn":"记不清的","ex":{"en":"blurred memories","cn":"模糊的记忆"}},{"en":"difficult to recognize, so differences are not clear","cn":"难以分辨的；模棱两可的","ex":{"en":"blurred distinctions/boundaries","cn":"含混不清的区别／界线"}}]},"examples":[{"en":"She suffered from dizziness and blurred vision.","cn":"她饱受头晕目眩之苦。"},{"en":"blurred distinctions/boundaries","cn":"含混不清的区别/界线"}],"base":"blur"},"blockbuster":{"media":{"uk":"media/uk/blockbuster__gb_1.mp3","us":"media/us/blockbuster__us_1.mp3"},"oxford":{"phon":"ˈblɒkbʌstə(r)","pos":"noun","senses":[{"en":"something very successful, especially a very successful book or film","cn":"一鸣惊人的事物；（尤指）非常成功的书（或电影）","ex":{"en":"a Hollywood blockbuster","cn":"一部好莱坞大片"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"轰动一时的电影；一度热卖的畅销书","en":"A blockbuster is a film or book that is very popular and successful, usually because it is very exciting."}]},"examples":[{"en":"a Hollywood blockbuster","cn":"一部好莱坞大片"},{"en":"a blockbusting performance","cn":"引起轰动的演出"}]},"bloated":{"media":{"uk":"media/uk/bloated__gb_1.mp3","us":"media/us/bloated__us_1.mp3"},"oxford":{"phon":"ˈbləʊtɪd","pos":"adjective","senses":[{"en":"full of liquid or gas and therefore bigger than normal, in a way that is unpleasant","cn":"膨胀的；肿胀的；臃肿的","lab":"figurative","ex":{"en":"a bloated body floating in the canal","cn":"运河里一具发胀的浮尸"}},{"en":"full of food and feeling uncomfortable","cn":"饮食过度的；胃胀的","ex":{"en":"I felt bloated after the huge meal they'd served.","cn":"吃过他们提供的大餐后，我觉得肚子胀得很。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（身体或身体某部位）肿胀的，膨胀的，发胀的","en":"If someone's body or a part of their body is bloated, it is much larger than normal, usually because it has a lot of liquid or gas inside it.","ex":{"en":"...the bloated body of a dead bullock","cn":"一头死的小阉牛肿胀的尸体"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"吃撑了的；肚子胀的","en":"If you feel bloated after eating a large meal, you feel very full and uncomfortable.","ex":{"en":"Diners do not want to leave the table feeling bloated.","cn":"食客们不想吃到肚子胀鼓鼓的才离开饭桌。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（机构）臃肿的，人浮于事的","en":"If you describe an organization as bloated, you mean that it is larger and less efficient than it should be.","ex":{"en":"...its massive state apparatus and bloated bureaucracy.","cn":"它那庞大的国家机关和臃肿的官僚机构"}}]},"examples":[{"en":"I felt bloated after the huge meal they'd served.","cn":"吃过他们提供的大餐后，我觉得肚子胀得很。"},{"en":"a bloated body floating in the canal","cn":"运河里一具发胀的浮尸"}]},"blink":{"oxford":{"phon":"blɪŋk","pos":"verb","senses":[{"en":"when you blink or blink your eyes or your eyes blink, you shut and open your eyes quickly","cn":"眨眼睛","g":"[intransitive, transitive]","ex":{"en":"He blinked in the bright sunlight.","cn":"他在强烈的阳光下直眨眼睛。"}},{"en":"to shine with an unsteady light; to flash on and off","cn":"闪烁；明灭","g":"[intransitive]","ex":{"en":"Suddenly a warning light blinked.","cn":"突然有一盏警告灯开始闪亮。"}},{"en":"the act of shutting and opening your eyes very quickly","cn":"眨眼睛","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"眨（眼）","en":"When you blink or when you blink your eyes, you shut your eyes and very quickly open them again.","ex":{"en":"Kathryn blinked and forced a smile","cn":"凯瑟琳眨了眨眼睛，挤出一丝微笑。"}},{"pos":"VERB 动词","cn":"（灯光）闪烁，闪动，忽明忽灭","en":"When a light blinks, it flashes on and off.","ex":{"en":"Green and yellow lights blinked on the surface of the harbour","cn":"海港的水面上闪烁着绿色和黄色的灯光。"}},{"pos":"PHRASE 短语","cn":"一眨眼的工夫；转眼之间；瞬间","en":"If you say that something happens in the blink of an eye, you mean that it happens very quickly.","ex":{"en":"It was all over in the blink of an eye.","cn":"转眼之间，一切都结束了。"}},{"pos":"PHRASE 短语","cn":"（机器）不能正常工作，出故障，出毛病","en":"If a machine goes on the blink, it stops working properly.","ex":{"en":"...an old TV that's on the blink.","cn":"坏了的旧电视机"}}]},"media":{"uk":"media/uk/blink__gb_1.mp3","us":"media/us/blink__us_1.mp3"},"examples":[{"en":"When I told him the news he didn't even blink (= showed no surprise at all).","cn":"我把那个消息告诉他时，他眼都没眨一下。"},{"en":"He blinked in the bright sunlight.","cn":"他在强烈的阳光下直眨眼睛。"}]},"blend":{"media":{"uk":"media/uk/blend__gb_1.mp3","us":"media/us/blend__us_1.mp3"},"oxford":{"phon":"blend","pos":"verb","senses":[{"en":"to mix two or more substances together","cn":"使混合；掺和","g":"[transitive]","ex":{"en":"Blend the flour with the milk to make a smooth paste.","cn":"把面粉和牛奶调成均匀的面糊。"}},{"en":"to form a mixture with something","cn":"（和某物）混合，融合","g":"[intransitive]","ex":{"en":"Oil does not blend with water.","cn":"油不溶于水。"}},{"en":"to combine with something in an attractive or effective way; to combine something in this way","cn":"（使）调和，协调，融合","g":"[intransitive, transitive]","ex":{"en":"The old and new buildings blend together perfectly.","cn":"新旧建筑物相映成趣。"}},{"en":"to produce something by mixing different types together","cn":"调制；配制","g":"[transitive, usually passive]","ex":{"en":"blended whisky/tea","cn":"调配的威士忌／茶"}},{"en":"a mixture of different types of the same thing","cn":"（同一事物中不同类型的）混合品，混合物","ex":{"en":"a blend of tea","cn":"调制茶"},"pos":"noun"},{"en":"a pleasant or useful combination of different things","cn":"（不同事物的）和谐结合，融合","g":"[usually singular]","ex":{"en":"a blend of youth and experience","cn":"年轻而且有经验"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP-ERG","cn":"（使）混合；调和；掺和","en":"If you blend substances together or if they blend, you mix them together so that they become one substance.","ex":{"en":"Blend the butter with the sugar and beat until light and creamy","cn":"把糖掺入黄油然后搅拌至滑软细腻。"}},{"pos":"N-COUNT 可数名词","cn":"（有用或令人愉快的事物的）融合，混合，组合","en":"A blend of things is a mixture or combination of them that is useful or pleasant.","ex":{"en":"The public areas offer a subtle blend of traditional charm with modern amenities.","cn":"这些公共场所将传统魅力和现代设施巧妙地融合在了一起。"}},{"pos":"V-RECIP 相互动词","cn":"（颜色、声音或风格）融合，交融，协调","en":"When colours, sounds, or styles blend, they come together or are combined in a pleasing way.","ex":{"en":"You could paint the walls and ceilings the same colour so they blend together.","cn":"你可以把墙和天花板粉刷成同一种颜色，这样看上去浑然一体。"}},{"pos":"VERB 动词","cn":"结合，融合，综合（想法、政策和风格）","en":"If you blend ideas, policies, or styles, you use them together in order to achieve something.","ex":{"en":"His 'cosmic vision' is to blend Christianity with 'the wisdom of all world religions'.","cn":"他的“远大设想”就是将基督教和“全世界所有宗教的智慧”融为一体。"}},{"pos":"","cn":"","en":"相关词组：blend in"}]},"examples":[{"en":"Their music blends traditional and modern styles.","cn":"他们的音乐融合了传统和现代风格。"},{"en":"Beat the butter and sugar; then blend in the egg.","cn":"把黄油和糖打好，然后调入鸡蛋。"}]},"blowing":{"lemma":"blow"},"blockage":{"oxford":{"phon":"ˈblɒkɪdʒ","pos":"noun","senses":[{"en":"a thing that blocks flow or movement, for example of a liquid in a narrow place","cn":"造成阻塞的东西；阻塞物","ex":{"en":"a blockage in an artery/a pipe/a drain","cn":"动脉／管道／排水沟堵塞物"}},{"en":"the state of being blocked","cn":"堵塞；阻塞","ex":{"en":"to cause/clear the blockage","cn":"引起／疏通阻塞"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"堵塞物；障碍物；堵塞","en":"A blockage in a pipe, tube, or tunnel is an object which blocks it, or the state of being blocked.","ex":{"en":"The logical treatment is to remove this blockage.","cn":"合理的治疗方法就是清除堵塞物。"}}]},"media":{"uk":"media/uk/blockage__gb_1.mp3","us":"media/us/blockage__us_1.mp3"},"examples":[{"en":"a blockage in an artery/a pipe/a drain","cn":"动脉/管道/排水沟堵塞物"},{"en":"to cause/clear the blockage","cn":"引起/排除阻塞"}]},"blind":{"media":{"uk":"media/uk/blind__gb_1.mp3","us":"media/us/blind__us_1.mp3","img":["media/ldoce/img/ldoce_028.png"]},"oxford":{"phon":"blaɪnd","pos":"adjective","senses":[{"en":"not able to see","cn":"瞎的；失明的","ex":{"en":"Doctors think he will go blind.","cn":"医生们认为他会失明。"}},{"en":"people who are blind","cn":"盲人","g":"[plural]","lab":"old-fashioned","ex":{"en":"recorded books for the blind","cn":"为盲人制作的录音书"}},{"en":"not noticing or realizing something","cn":"（对某事）视而不见的，未察觉的","ex":{"en":"She is blind to her husband's faults.","cn":"她对丈夫的过错毫无察觉。"}},{"en":"seeming to be unreasonable, and accepted without question; seeming to be out of control","cn":"盲目接受的；不能自制的","g":"[usually before noun]","ex":{"en":"blind faith/obedience","cn":"盲目的信念；盲从"}},{"en":"that cannot be controlled by reason","cn":"无理性的","g":"[usually before noun]","ex":{"en":"blind chance","cn":"盲目的偶然性"}},{"en":"that a driver in a car cannot see, or cannot see around","cn":"汽车司机看不见的；隐蔽的","ex":{"en":"a blind driveway","cn":"视线有盲区的车道"}},{"en":"that does not make a difference between people on the basis of the quality mentioned, or favour one group over another","cn":"不区分…的；没有歧视的","ex":{"en":"In a piece of gender-blind casting, Hamlet is played by British actress Maxine Peake.","cn":"在一出选角不分性别的戏剧中，哈姆雷特由英国女演员马克辛·皮克扮演。"}},{"en":"to permanently destroy somebody’s ability to see","cn":"使变瞎；使失明","ex":{"en":"She was blinded in the explosion.","cn":"她在那场爆炸中双目失明了。"},"pos":"verb"},{"en":"to make it difficult for somebody to see for a short time","cn":"使眼花；使目眩","ex":{"en":"When she went outside she was temporarily blinded by the sun.","cn":"走出户外时，她一时被阳光照得眼睛昏花。"},"pos":"verb"},{"en":"to make somebody no longer able to think clearly or behave in a sensible way","cn":"使思维混沌；使失去判断力","ex":{"en":"His sense of loyalty blinded him to the truth.","cn":"他的赤诚忠心使他看不清真相。"},"pos":"verb"},{"en":"material that covers a window, often consisting of a roll of cloth that is fixed at the top of the window and can be pulled up and down","cn":"窗帘；（常指）卷帘","g":"[countable]","lab":"North American English also","ex":{"en":"She saw a figure through the blinds.","cn":"她透过窗帘看到一个身影。"},"pos":"noun"},{"en":"something people say or do to hide the truth about something in order to trick other people","cn":"用以蒙蔽人的言行；借口；托辞；幌子","g":"[singular]","pos":"noun"},{"en":"without being able to see; using instruments only","cn":"视线受阻地；仅靠仪表操纵地；盲目地","pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"盲的；瞎的；失明的","en":"Someone who is blind is unable to see because their eyes are damaged.","ex":{"en":"I started helping him run the business when he went blind","cn":"他失明以后，我就开始帮他打理生意。"}},{"pos":"VERB 动词","cn":"使…看不见；使…失明","en":"If something blinds you, it makes you unable to see, either for a short time or permanently.","ex":{"en":"The sun hit the windscreen, momentarily blinding him.","cn":"太阳照在挡风玻璃上，晃得他一时看不见东西。"}},{"pos":"ADJ 形容词","cn":"暂时看不见的；双眼模糊的；目眩的","en":"If you are blind with something such as tears or a bright light, you are unable to see for a short time because of the tears or light.","ex":{"en":"Her mother groped for the back of the chair, her eyes blind with tears.","cn":"她妈妈泪眼蒙眬地伸手去摸椅背。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"看不到的；视而不见的；没有意识到的","en":"If you say that someone is blind to a fact or a situation, you mean that they ignore it or are unaware of it, although you think that they should take notice of it or be aware of it.","ex":{"en":"David's good looks and impeccable manners had always made her blind to his faults","cn":"戴维英俊的长相和完美的举止总是让她对他的缺点视而不见。"}},{"pos":"VERB 动词","cn":"使无法意识到；使无视；使无法认清","en":"If something blinds you to the real situation, it prevents you from realizing that it exists or from understanding it properly.","ex":{"en":"He never allowed his love of Australia to blind him to his countrymen's faults.","cn":"他从来不会因为对澳大利亚的热爱而看不到自己同胞的缺点。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（信仰或行动）盲目的，不理智的","en":"You can describe someone's beliefs or actions as blind when you think that they seem to take no notice of important facts or behave in an unreasonable way.","ex":{"en":"...her blind faith in the wisdom of the Church","cn":"她对教会智慧的盲目信仰"}},{"pos":"ADJ 形容词","cn":"（拐角）不在视线中的，看不见的","en":"A blind corner is one that you cannot see round because something is blocking your view.","ex":{"en":"He tried to overtake three cars on a blind corner and crashed head-on into a lorry.","cn":"他试图在一个死角处超过前面的三辆车，结果一头撞在了一辆卡车上。"}},{"pos":"ADJ 形容词","cn":"无窗的；无门的；没有开口的；封死的","en":"A blind wall or building is one which has no windows or doors.","ex":{"en":"I remembered a huddle of stone buildings with blind walls.","cn":"我记得一片没有窗户的石头建筑。"}},{"pos":"N-COUNT 可数名词","cn":"百叶窗；卷帘","en":"A blind is a roll of cloth or paper which you can pull down over a window as a covering."},{"pos":"PHRASE 短语","cn":"对…视而不见；对…假装看不见","en":"If you say that someone is turning a blind eye to something bad or illegal that is happening, you mean that you think they are pretending not to notice that it is happening so that they will not have to do anything about it.","ex":{"en":"Teachers are turning a blind eye to pupils smoking at school, a report reveals today","cn":"今日一篇报道称，老师们对学生在学校抽烟睁一只眼闭一只眼。"}}]},"examples":[{"en":"I must have been blind not to realize the danger we were in.","cn":"当时我一定是眼瞎了，竟然没有意识到我们所处的危险。"},{"en":"When she went outside she was temporarily blinded by the sun.","cn":"走出户外时，她一时被阳光照得眼睛昏花。"}]},"blood":{"media":{"uk":"media/uk/blood__gb_1.mp3","us":"media/us/blood__us_1.mp3"},"oxford":{"phon":"blʌd","pos":"noun","senses":[{"en":"the red liquid that flows through the bodies of humans and animals","cn":"血","g":"[uncountable]","ex":{"en":"He lost a lot of blood in the accident.","cn":"他在那场事故中流了很多血。"}},{"en":"having the type of blood mentioned","cn":"有…类型的血的","ex":{"en":"cold-blooded reptiles","cn":"冷血爬行动物"}},{"en":"family origins","cn":"血统；家世","g":"[uncountable]","lab":"formal","ex":{"en":"She is of noble blood.","cn":"她有贵族血统。"}},{"en":"a rich and fashionable man","cn":"纨绔子弟；花花公子","g":"[countable]","lab":"British English, old-fashioned，，","ex":{"en":"a young blood","cn":"血气方刚的青年。"}},{"en":"to give somebody their first experience of an activity","cn":"让（新人）初试","pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"血；血液","en":"Blood is the red liquid that flows inside your body, which you can see if you cut yourself."},{"pos":"N-UNCOUNT 不可数名词","cn":"血统；出身；门第；家世","en":"You can use blood to refer to the race or social class of someone's parents or ancestors.","ex":{"en":"There was Greek blood in his veins","cn":"他有希腊血统。"}},{"pos":"PHRASE 短语","cn":"仇恨；憎恶感；厌恶感","en":"If you say that there is bad blood between people, you mean that they have argued about something and dislike each other.","ex":{"en":"There is, it seems, some bad blood between Mills and the Baldwins.","cn":"米尔斯和鲍德温一家人好像有些不和。"}},{"pos":"PHRASE 短语","cn":"要求惩罚；要求严惩","en":"If you say that people are baying for blood, you mean that they are demanding that someone should be hurt or punished.","ex":{"en":"And so what will he say to those who have been baying for his blood?","cn":"那么，他又会对那些一直强烈要求制裁他的人说些什么呢？"}},{"pos":"PHRASE 短语","cn":"出身高贵；名门出身","en":"If you say that someone has blue blood, you mean that they are from a family that has a high social rank."},{"pos":"PHRASE 短语","cn":"使怒不可遏；使怒火中烧","en":"If you say that something makes your blood boil, you are emphasizing that it makes you very angry.","ex":{"en":"It makes my blood boil to think two thugs decided to pick on an innocent young girl.","cn":"一想到两个暴徒要欺负一个天真的小姑娘，我就满腔怒火。"}},{"pos":"PHRASE 短语","cn":"冷酷无情地；冷血地；残忍地","en":"If something violent and cruel is done in cold blood, it is done deliberately and in an unemotional way.","ex":{"en":"The crime had been committed in cold blood.","cn":"这一罪行极为残忍。"}},{"pos":"PHRASE 短语","cn":"使人不寒而栗；令人毛骨悚然","en":"If you say that something makes your blood run cold or makes your blood freeze, you mean that it makes you feel very frightened.","ex":{"en":"The rage in his eyes made her blood run cold","cn":"他眼中的怒火吓得她汗毛倒竖。"}},{"pos":"PHRASE 短语","cn":"手上沾了…的血；对…的死难辞其咎","en":"If you say that someone has a person's blood on their hands, you mean that they are responsible for that person's death.","ex":{"en":"He has my son's blood on his hands. I hope it haunts him for the rest of his days.","cn":"他手上沾了我儿子的血。我咒他余生不得安宁。"}},{"pos":"PHRASE 短语","cn":"天生的；遗传的；生来就有的","en":"If a quality or talent is in your blood, it is part of your nature, and other members of your family have it too.","ex":{"en":"Diplomacy was in his blood: his ancestors had been feudal lords","cn":"他天生擅长交际：他的祖先曾是封建领主。"}},{"pos":"PHRASE 短语","cn":"新鲜血液；新生力量；新成员","en":"You can use the expressions new blood ,fresh blood, or young blood to refer to people who are brought into an organization to improve it by thinking of new ideas or new ways of doing things.","ex":{"en":"There's been a major reshuffle of the cabinet to bring in new blood","cn":"内阁进行了重大改组，吸收了一些新鲜血液。"}},{"pos":"PHRASE 短语","cn":"向石取血，缘木求鱼（比喻很难办到或徒劳无功）","en":"If you say that doing something such as getting information or persuading someone to talk to you is like getting blood out of a stone or getting blood from a stone, you are emphasizing that it is very difficult and that people are not being very helpful. In American English, you can also say that it is like getting blood out of a turnip ."},{"pos":"PHRASE 短语","cn":"竭尽全力；呕心沥血","en":"If you say that someone sweats blood trying to do something, you are emphasizing that they try very hard to do it.","ex":{"en":"I had to sweat blood for an M.A.","cn":"我得拼命争取获得硕士学位。"}},{"pos":"PHRASE 短语","cn":"取得初步胜利；最先占上风","en":"If you say that someone draws first blood, you mean that they have had a success at the beginning of a competition or conflict.","ex":{"en":"The home side drew first blood with a penalty from Murray Strang.","cn":"主场球队依靠默里·斯特朗的罚球而旗开得胜。"}},{"pos":"PHRASE 短语","cn":"血汗；艰苦的努力","en":"If you refer to something as involving blood, sweat, and tears, you mean that it is a very hard thing to do and requires a lot of effort.","ex":{"en":"Why do apparently sane people go through all the blood, sweat, tears and heartache involved in getting a PhD?","cn":"为什么那些看起来神志正常的人会拼了命地要拿到一个博士学位？"}},{"pos":"PHRASE 短语","cn":"血浓于水；家人总比外人亲","en":"People say 'blood is thicker than water' when they mean that their loyalty to their family is greater than their loyalty to anyone else.","ex":{"en":"Families have their problems and jealousies, but blood is thicker than water.","cn":"家家有本难念的经，也都难免互生嫉妒，但总归血浓于水。"}},{"pos":"","cn":"","en":"flesh and blood→see: ; own flesh and blood→see: ;"}]},"examples":[{"en":"Blood was pouring out of a cut on her head.","cn":"血不断地从她头上的伤口中涌出。"},{"en":"He lost a lot of blood in the accident.","cn":"他在那场事故中流了很多血。"}]},"blob":{"oxford":{"phon":"blɒb","pos":"noun","senses":[{"en":"a small amount or drop of something, especially a liquid; a small area of colour","cn":"（尤指液体的）一点，一滴；（颜色的）一小片，斑点","ex":{"en":"a blob of ink","cn":"一滴墨水"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（黏稠液体的）一滴，一团","en":"A blob of thick or sticky liquid is a small, often round, amount of it.","ex":{"en":"...a blob of chocolate mousse","cn":"一团巧克力奶油冻"}},{"pos":"N-COUNT 可数名词","cn":"（模糊不清的）一团，一点","en":"You can use blob to refer to something that you cannot see very clearly, for example because it is in the distance.","ex":{"en":"You could just see vague blobs of faces.","cn":"你只能看到些模糊的人脸。"}}]},"media":{"uk":"media/uk/blob__gb_1.mp3","us":"media/us/blob__us_1.mp3"},"examples":[{"en":"a pink blob","cn":"粉红色斑点"},{"en":"a blob of ink","cn":"一滴墨水"}]},"blue-collar":{"oxford":{"phon":"ˌbluː ˈkɒlə(r)","pos":"adjective","senses":[{"en":"connected with people who do physical work in industry","cn":"从事体力劳动的；蓝领的","ex":{"en":"blue-collar workers/voters/votes","cn":"蓝领工人／选民／选票"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"蓝领的；从事体力劳动的","en":"Blue-collar workers work in industry, doing physical work, rather than in offices.","ex":{"en":"By 1925, blue-collar workers in manufacturing industry had become the largest occupational group.","cn":"到1925年，制造业的蓝领工人已成为最大的职业群体。"}}]},"media":{"uk":"media/uk/blue_collar_1_gb_1.mp3","us":"media/us/blue_collar_1_us_1.mp3"},"examples":[{"en":"blue-collar workers/voters/votes","cn":"蓝领工人/选民/选票"}]},"blossom":{"media":{"img":["media/pic/tree_bark_comp.jpg","media/thumb/twig.jpg"],"uk":"media/uk/blossom__gb_1.mp3","us":"media/us/blossom__us_1.mp3"},"oxford":{"phon":"ˈblɒsəm","pos":"noun","senses":[{"en":"a flower or a mass of flowers, especially on a fruit tree or bush","cn":"（尤指果树或灌木的）花朵，花簇","ex":{"en":"cherry/orange/apple blossom","cn":"樱桃花；橘子花；苹果花"}},{"en":"to produce blossom","cn":"开花","g":"[intransitive]","ex":{"en":"The cherry trees blossomed early this year.","cn":"樱桃树今年开花早。"},"pos":"verb"},{"en":"to become more healthy, confident or successful","cn":"变得更加健康（或自信、成功）","g":"[intransitive]","ex":{"en":"She has visibly blossomed over the last few months.","cn":"她近几个月以来身体明显好多了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（树木的）花， 花簇","en":"Blossom is the flowers that appear on a tree before the fruit.","ex":{"en":"The cherry blossom came out early in Washington this year.","cn":"今年华盛顿的樱花开得很早。"}},{"pos":"VERB 动词","cn":"兴盛；变得有魅力；变得成功","en":"If someone or something blossoms, they develop good, attractive, or successful qualities.","ex":{"en":"Why do some people take longer than others to blossom?","cn":"为什么有的人比他人大器晚成？"}},{"pos":"VERB 动词","cn":"（树木）开花","en":"When a tree blossoms, it produces blossom.","ex":{"en":"Rain begins to fall and peach trees blossom.","cn":"开始下雨了，桃树也开花了。"}}]},"examples":[{"en":"She has visibly blossomed over the last few months.","cn":"她近几个月以来身体明显好多了。"},{"en":"Their friendship blossomed into love.","cn":"他们的友谊发展成了爱情。"}]},"bloodshot":{"oxford":{"phon":"ˈblʌdʃɒt","pos":"adjective","senses":[{"en":"with the part that is usually white full of red lines because of lack of sleep, etc.","cn":"布满血丝的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（眼睛）充血的，布满血丝的","en":"If your eyes are bloodshot, the parts that are usually white are red or pink. Your eyes can be bloodshot for a variety of reasons, for example because you are tired or you have drunk too much alcohol.","ex":{"en":"John's eyes were bloodshot and puffy.","cn":"约翰双眼红肿。"}}]},"media":{"uk":"media/uk/bloodshot__gb_1.mp3","us":"media/us/bloodshot__us_1.mp3"}},"bluff":{"media":{"uk":"media/uk/bluff__gb_1.mp3","us":"media/us/bluff__us_1.mp3"},"oxford":{"phon":"blʌf","pos":"verb","senses":[{"en":"to try to make somebody believe that you will do something that you do not really intend to do, or that you know something that you do not really know","cn":"虚张声势；唬人；吹牛","ex":{"en":"I don't think he'll shoot—I think he's just bluffing.","cn":"我认为他不会开枪，我想他不过是在吓唬人。"}},{"en":"an attempt to trick somebody by making them believe that you will do something when you really have no intention of doing it, or that you know something when you do not, in fact, know it","cn":"虚张声势的做法；唬人","g":"[uncountable, countable]","ex":{"en":"It was just a game of bluff.","cn":"那只不过是唬人的把戏。"},"pos":"noun"},{"en":"a steep cliff or slope, especially by the sea or a river","cn":"（尤指海边或河边的）峭壁，陡岸","g":"[countable]","pos":"noun"},{"en":"very direct and cheerful, with good intentions, although not always very polite","cn":"直率豪爽的（尽管有时不够礼貌）","ex":{"en":"Beneath his bluff exterior he was a sensitive man.","cn":"他外表大大咧咧，但其实是个敏感的人。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"欺骗；误导；吓唬；虚张声势","en":"A bluff is an attempt to make someone believe that you will do something when you do not really intend to do it.","ex":{"en":"The letter was a bluff","cn":"这封信不过是吓唬人罢了。"}},{"pos":"PHRASE 短语","cn":"（因料到对方不敢行动而）要求…摊牌，接受…的挑战","en":"If you call someone's bluff, you tell them to do what they have been threatening to do, because you are sure that they will not really do it.","ex":{"en":"The Socialists have decided to call the opposition's bluff.","cn":"社会党人已经决定接受对方的挑战。"}},{"pos":"VERB 动词","cn":"欺骗；误导；吓唬；虚张声势","en":"If you bluff, you make someone believe that you will do something when you do not really intend to do it, or that you know something when you do not really know it.","ex":{"en":"Either side, or both, could be bluffing","cn":"任何一方，或者双方，都可能是在故弄玄虚。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指河边或海边的）悬崖，峭壁，陡岸","en":"A bluff is a steep cliff or bank, especially by a river or the sea.","ex":{"en":"...a high bluff over the Congaree River.","cn":"康加里河边高耸的峭壁"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坦率的；坦白的；直言的","en":"If you describe someone, usually a man, as bluff, you mean that they have a very direct way of speaking and behaving.","ex":{"en":"He comes across as a man with a bluff exterior who, beyond that, is difficult to get to know","cn":"他给人感觉是一个直来直去的人，但内心却让人捉摸不透。"}}]},"examples":[{"en":"He said he would resign if he didn't get more money, but it was only a bluff.","cn":"他说如果不给他加薪他就辞职，但那不过是虚张声势而已。"},{"en":"I don't think he'll shoot — I think he's just bluffing.","cn":"我认为他不会开枪，我想他不过是在吓唬人。"}]},"blamed":{"lemma":"blame"},"blur":{"media":{"uk":"media/uk/blur__gb_1.mp3","us":"media/us/blur__us_1.mp3"},"oxford":{"phon":"blɜː(r)","pos":"noun","senses":[{"en":"a shape that you cannot see clearly, often because it is moving too fast","cn":"（移动的）模糊形状","ex":{"en":"His arm was a rapid blur of movement as he struck.","cn":"他出击时胳膊快速一晃，令人眼花缭乱。"}},{"en":"something that you cannot remember clearly","cn":"模糊的记忆","ex":{"en":"The events of that day were just a blur.","cn":"那天发生的事只剩一片模糊的记忆。"}},{"en":"if the shape or outline of something blurs, or if something blurs it, it becomes less clear and sharp","cn":"（使）变得模糊不清","g":"[intransitive, transitive]","ex":{"en":"The writing blurred and danced before his eyes.","cn":"字迹变得一片模糊，在他眼前晃动。"},"pos":"verb"},{"en":"if something blurs your eyes or vision, or your eyes or vision blur, you cannot see things clearly","cn":"（使）视线模糊；（使）看不清","g":"[transitive, intransitive]","ex":{"en":"Tears blurred her eyes.","cn":"泪水模糊了她的视线。"},"pos":"verb"},{"en":"to become or make it become difficult to recognize a clear difference between things","cn":"变模糊；使模糊","g":"[intransitive, transitive]","ex":{"en":"The differences between art and life seem to have blurred.","cn":"艺术和生活之间的差别似乎已变得模糊不清。"},"pos":"verb"},{"en":"a British pop group, one of the most popular of the Britpop groups of the 1990s. Their most successful albums include Parklife (1994), The Great Escape (1995) and Think Tank (2003).","cn":"模糊乐队（英国流行乐团，是1990年代最流行的英国流行乐团之一。他们最成功的专辑包括 Parklife，The Great Escape 和 Think Tank）","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"模糊形状；模糊的区域","en":"A blur is a shape or area which you cannot see clearly because it has no distinct outline or because it is moving very fast.","ex":{"en":"Out of the corner of my eye I saw a blur of movement on the other side of the glass","cn":"从眼角余光中我看到玻璃的另一边隐约有东西在移动。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）变得模糊不清","en":"When a thing blurs or when something blurs it, you cannot see it clearly because its edges are no longer distinct.","ex":{"en":"This creates a spectrum of colours at the edges of objects which blurs the image","cn":"这在物体的边缘形成了一道色谱，使图像变得模糊不清。"}},{"pos":"VERB 动词","cn":"使（想法、区别等）模糊；使（想法、区别等）不明晰","en":"If something blurs an idea or a distinction between things, that idea or distinction no longer seems clear.","ex":{"en":"...her belief that scientists are trying to blur the distinction between 'how' and 'why' questions","cn":"她认为科学家们试图模糊“如何”和“为什么”这两类问题之间的区别"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（视力）模糊；（使）看不清楚","en":"If your vision blurs, or if something blurs it, you cannot see things clearly.","ex":{"en":"Her eyes, behind her glasses, began to blur","cn":"她藏在眼镜后面的双眼变得模糊起来。"}}]},"examples":[{"en":"The differences between art and life seem to have blurred.","cn":"艺术和生活之间的差别似乎已变得模糊不清。"},{"en":"His arm was a rapid blur of movement as he struck.","cn":"他出击时胳膊快速一晃，令人眼花缭乱。"}]},"bleak":{"media":{"uk":"media/uk/bleak__gb_1.mp3","us":"media/us/bleak__us_1.mp3"},"oxford":{"phon":"bliːk","pos":"adjective","senses":[{"en":"not giving any reason to have hope or expect anything good","cn":"暗淡的；没希望的","ex":{"en":"a bleak outlook/prospect","cn":"暗淡的前景／前途"}},{"en":"cold and unpleasant","cn":"阴冷的","ex":{"en":"a bleak winter’s day","cn":"一个阴冷的冬日"}},{"en":"exposed, empty, or with no pleasant features","cn":"无遮掩的；荒凉的；索然无味的","ex":{"en":"a bleak landscape/hillside/moor","cn":"荒芜的景色／山坡／野地"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情形）没有希望的，前景暗淡的","en":"If a situation is bleak, it is bad, and seems unlikely to improve.","ex":{"en":"The immediate outlook remains bleak","cn":"近期前景依然暗淡。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地方）凄清的，荒凉的，萧瑟的","en":"If you describe a place as bleak, you mean that it looks cold, empty, and unattractive.","ex":{"en":"The island's pretty bleak.","cn":"这座岛屿一片荒凉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）阴冷的，寒冷的","en":"When the weather is bleak, it is cold, dull, and unpleasant.","ex":{"en":"The weather can be quite bleak on the coast.","cn":"沿海地区的天气会非常阴冷。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）无精打采的，沮丧的，阴郁的","en":"If someone looks or sounds bleak, they look or sound depressed, as if they have no hope or energy.","ex":{"en":"His face was bleak","cn":"他脸色阴郁。"}}]},"examples":[{"en":"‘There seems no hope,’ she said bleakly. “","cn":"好像没希望了。”她黯然地说。"},{"en":"The future looks bleak for the fishing industry.","cn":"渔业前景暗淡。"}]},"blindly":{"media":{"uk":"media/uk/blindly__gb_1.mp3","us":"media/us/blindly__us_1.mp3"},"oxford":{"phon":"ˈblaɪndli","pos":"adverb","senses":[{"en":"without being able to see what you are doing","cn":"摸黑地；在黑暗中","ex":{"en":"She groped blindly for the light switch in the dark room.","cn":"她在黑暗的房间里摸索电灯开关。"}},{"en":"without thinking about what you are doing","cn":"不加思考地；盲目地","ex":{"en":"He wanted to decide for himself instead of blindly following his parents' advice.","cn":"他想自己拿主意，而不是盲目听从他父母的意见。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"盲目地；未经思考地","en":"If you say that someone does something blindly, you mean that they do it without having enough information, or without thinking about it.","ex":{"en":"Don't just blindly follow what the banker says","cn":"不要盲目听信银行家的话。"}}]},"examples":[{"en":"He wanted to decide for himself instead of blindly following his parents' advice.","cn":"他想自己拿主意，而不是盲目听从他父母的意见。"},{"en":"She groped blindly for the light switch in the dark room.","cn":"她在黑暗的房间里摸索电灯开关。"}]},"black":{"media":{"uk":"media/uk/black__gb_1.mp3","us":"media/us/black__us_1.mp3"},"oxford":{"phon":"blæk","pos":"adjective","senses":[{"en":"having the very darkest colour, like coal or the sky at night","cn":"黑的；黑色的","sc":"colour","ex":{"en":"a shiny black car","cn":"发亮的黑汽车"}},{"en":"without light; completely dark","cn":"黑暗的；漆黑的","sc":"with no light","ex":{"en":"a black night","cn":"漆黑的夜晚"}},{"en":"belonging to a group of people who have dark skin, especially people who come from or whose ancestors came from Africa; connected with black people","cn":"黑人的","sc":"people","ex":{"en":"The film is set in a historically black community.","cn":"这部电影以一个历史悠久的黑人社区为背景。"}},{"en":"without milk","cn":"不加牛奶的","sc":"tea/coffee","ex":{"en":"Two black coffees, please.","cn":"请来两杯不加牛奶的咖啡。"}},{"en":"very dirty; covered with dirt","cn":"很脏的；布满污垢的","sc":"dirty","ex":{"en":"chimneys black with smoke","cn":"满布烟尘的烟囱"}},{"en":"full of anger or hate","cn":"愤怒的；仇恨的","sc":"angry","ex":{"en":"She's been in a really black mood all day.","cn":"她一整天都心情很坏。"}},{"en":"without hope; very depressing","cn":"无希望的；令人沮丧的","sc":"depressing","ex":{"en":"The future looks pretty black.","cn":"前景看来很暗淡。"}},{"en":"evil or immoral","cn":"邪恶的；不道德的","lab":"literary","sc":"evil","ex":{"en":"black deeds/lies","cn":"邪恶行为；昧良心的谎言"}},{"en":"dealing with unpleasant or terrible things, such as murder, in a humorous way","cn":"黑色的（以幽默的方式对待讨厌的或可怕的事物，如凶杀）","sc":"humour","ex":{"en":"‘Good place to bury the bodies,’ she joked with black humour.","cn":"“真是个掩埋尸体的风水宝地。”她以黑色幽默打趣道。"}},{"en":"the very darkest colour, like night or coal","cn":"黑色","g":"[uncountable]","sc":"colour","ex":{"en":"the black of the night sky","cn":"夜空的漆黑"},"pos":"noun"},{"en":"a member of a group of people who have dark skin, especially people who come from or whose ancestors came from Africa","cn":"黑人","g":"[countable, usually plural]","lab":"offensive","sc":"people","pos":"noun"},{"en":"to refuse to deal with goods or to do business with somebody as a political protest","cn":"抵制；拒绝处理（货物）；拒绝同（某人）做生意","lab":"British English","ex":{"en":"The unions have blacked all imports from the country.","cn":"工会拒绝处理从这个国家进口的所有货物。"},"pos":"verb"},{"en":"to make something black","cn":"使变黑；染黑；涂黑","pos":"verb"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"黑色","en":"Something that is black is of the darkest colour that there is, the colour of the sky at night when there is no light at all.","ex":{"en":"She was wearing a black coat with a white collar","cn":"她穿着一件白领黑外套。"}},{"pos":"ADJ 形容词","cn":"（人）黑色人种的；（尤指）非洲黑人的","en":"A black person belongs to a race of people with dark skins, especially a race from Africa.","ex":{"en":"He worked for the rights of black people","cn":"他为争取黑人权利而工作。"}},{"pos":"N-COUNT 可数名词","cn":"黑人（可能具冒犯意味）","en":"Black people are sometimes referred to as blacks. This use could cause offence.","ex":{"en":"There are about thirty-one million blacks in the US.","cn":"美国大约有3,100万黑人。"}},{"pos":"ADJ 形容词","cn":"（咖啡、茶）不加牛奶（或奶油）的","en":"Black coffee or tea has no milk or cream added to it.","ex":{"en":"A cup of black tea or black coffee contains no calories","cn":"一杯不加牛奶的茶或咖啡不含热量。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极糟糕的；坏透顶的；黑暗的","en":"If you describe a situation as black, you are emphasizing that it is very bad indeed.","ex":{"en":"It was, he said later, one of the blackest days of his political career","cn":"后来他说，这是他政治生涯中最黑暗的日子之一。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情绪）沮丧的，低落的，忧郁的","en":"If someone is in a black mood, they feel very miserable and depressed.","ex":{"en":"In late 1975, she fell into a black depression","cn":"在1975年底，她陷入了情绪的低谷。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"残忍的；恶毒的；邪恶的","en":"You use black to describe things that you consider to be very cruel or wicked.","ex":{"en":"I think their crime is a blacker one than mere exploitation.","cn":"我想他们的罪行比单纯的剥削更残忍。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（幽默）黑色的","en":"Black humour involves jokes about sad or difficult situations.","ex":{"en":"'So you can all go over there and get shot,' he said, with the sort of black humour common among British troops here","cn":"“所以你们都可以到那里去挨枪子儿，”他说道，口吻中透着这里英国部队惯用的黑色幽默。"}},{"pos":"ADJ 形容词","cn":"巫术的；妖术的","en":"People who believe in black magic believe that it is possible to communicate with evil spirits.","ex":{"en":"He was also alleged to have conducted black magic ceremonies","cn":"据称他还做了法。"}},{"pos":"VERB 动词","cn":"把（眼睛）打得发青","en":"If someone blacks another person's eye, they punch or hit that person in the eye, causing it to bruise and look black.","ex":{"en":"Her husband blacked her eye","cn":"她丈夫把她的眼睛打青了。"}},{"pos":"PHRASE 短语","cn":"（伤得）青一块紫一块","en":"If you say that someone is black and blue, you mean that they are badly bruised.","ex":{"en":"Whenever she refused, he'd beat her black and blue","cn":"只要她拒绝他，他就会把她打得青一块紫一块。"}},{"pos":"PHRASE 短语","cn":"有盈余；有结余","en":"If a person or an organization is in the black, they do not owe anyone any money.","ex":{"en":"Remington's operations in Japan are now in the black","cn":"雷明顿在日本的业务现在有盈利。"}},{"pos":"PHRASE 短语","cn":"怒视；恶狠狠的盯视","en":"If someone gives you a black look, they look at you in a way that shows that they are very angry about something.","ex":{"en":"Passing my stall, she cast black looks at the amount of stuff still unsold.","cn":"她经过我的货摊的时候，怒气冲冲地看了几眼还没有卖出去的东西。"}},{"pos":"","cn":"","en":"相关词组：black out"}]},"examples":[{"en":"It's been another black day for the north-east with the announcement of further job losses.","cn":"东北部又经历了一个黑色的日子，当地公布的失业人数再度上升。"},{"en":"‘Good place to bury the bodies,’ she joked with black humour. “","cn":"真是个掩埋尸体的风水宝地。”她以黑色幽默打趣道。"}]},"blade":{"media":{"img":["media/pic/blade_comp.jpg","media/thumb/blade.jpg"],"uk":"media/uk/blade__gb_1.mp3","us":"media/us/blade__us_1.mp3"},"oxford":{"phon":"bleɪd","pos":"noun","senses":[{"en":"the flat part of a knife, tool or machine, which has a sharp edge or edges for cutting","cn":"刀身；刀片；刀刃","ex":{"en":"The machine comes with a plastic guard over the blade to protect the operator.","cn":"该机器在刀片上配有塑料防护罩，以保护操作员。"}},{"en":"one of the flat parts that turn around in an engine or on a helicopter","cn":"（机器上旋转的）叶片；桨叶","ex":{"en":"the blades of a propeller","cn":"螺旋桨叶"}},{"en":"the flat wide part of an oar (= one of the long straight pieces of wood that are used to row a boat) that goes in the water","cn":"（船桨的）桨叶，桨身"},{"en":"a single flat leaf of grass","cn":"（草的）叶片","ex":{"en":"Not a blade of grass stirred.","cn":"连一根草叶都没有动静。"}},{"en":"the flat metal part on the bottom of an ice skate","cn":"（溜冰鞋的）冰刀"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"刃；锋","en":"The blade of a knife, axe, or saw is the edge, which is used for cutting.","ex":{"en":"Many of these tools have sharp blades, so be careful.","cn":"这些工具中很多都有锋利的刀片，务必小心。"}},{"pos":"N-COUNT 可数名词","cn":"（螺旋桨的）叶片","en":"The blades of a propeller are the long, flat parts that turn round."},{"pos":"N-COUNT 可数名词","cn":"桨叶","en":"The blade of an oar is the thin flat part that you put into the water."},{"pos":"N-COUNT 可数名词","cn":"（草的）叶片","en":"A blade of grass is a single piece of grass."},{"pos":"See also:","cn":"","en":"→see: ;"}]},"examples":[{"en":"rotor blades on a helicopter","cn":"直升机的旋翼"},{"en":"the blades of a propeller","cn":"螺旋桨叶"}]},"blame":{"oxford":{"phon":"bleɪm","pos":"verb","senses":[{"en":"to think or say that somebody/something is responsible for something bad","cn":"把…归咎于；责怪；指责","ex":{"en":"She doesn't blame anyone for her father's death.","cn":"她没把她父亲的死归罪于任何人。"}},{"en":"responsibility for doing something badly or wrongly; saying that somebody is responsible for something","cn":"（坏事或错事的）责任；责备；指责","ex":{"en":"Why do I always get the blame for everything that goes wrong?","cn":"为什么出了事总是让我背黑锅？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"责怪；怪罪；归咎于","en":"If you blame a person or thing for something bad, you believe or say that they are responsible for it or that they caused it.","ex":{"en":"The commission is expected to blame the army for many of the atrocities","cn":"委员会理应谴责军队的诸多暴行。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（对坏事应负的）责任","en":"The blame for something bad that has happened is the responsibility for causing it or letting it happen.","ex":{"en":"Some of the blame for the miscarriage of justice must be borne by the solicitors","cn":"律师们应对误判负部分责任。"}},{"pos":"VERB 动词","cn":"怨；怪；责备","en":"If you say that you do not blame someone for doing something, you mean that you consider it was a reasonable thing to do in the circumstances.","ex":{"en":"I do not blame them for trying to make some money","cn":"我认为他们想赚一些钱也是情有可原的。"}},{"pos":"PHRASE 短语","cn":"…难辞其咎；应对…负责","en":"If someone is to blame for something bad that has happened, they are responsible for causing it.","ex":{"en":"If their forces were not involved, then who is to blame?","cn":"如果他们的部队没有介入，那么谁应该承担责任？"}},{"pos":"PHRASE 短语","cn":"只能怪自己","en":"If you say that someone has only themselves to blame or has no-one but themselves to blame, you mean that they are responsible for something bad that has happened to them and that you have no sympathy for them.","ex":{"en":"My life is ruined and I suppose I only have myself to blame.","cn":"我的一生都毁了，我想这只能怪我自己。"}}]},"media":{"uk":"media/uk/blame__gb_1.mp3","us":"media/us/blame__us_1.mp3"},"examples":[{"en":"‘I just slammed the phone down when he said that.’ ‘I don't blame you!’ “","cn":"他一说那话我就啪地一下挂了电话。” “你做得对！”"},{"en":"Call her if you like, but don't blame me if she's angry.","cn":"你想给她打电话就打吧，不过要是她生气就别怪我。"}]},"blessed":{"media":{"uk":"media/uk/blessed__gb_2.mp3","us":"media/us/blessed__us_2.mp3"},"oxford":{"phon":"ˈblesɪd","pos":"adjective","senses":[{"en":"holy","cn":"神圣的","ex":{"en":"the Blessed Virgin Mary","cn":"荣福童贞马利亚"}},{"en":"(in religious language) lucky","cn":"（宗教用语）有福的","ex":{"en":"Blessed are the poor.","cn":"神贫的人是有福的。"}},{"en":"giving you a sense of peace or a feeling of freedom from worry or pain","cn":"愉快安宁的；无忧无虑的","g":"[only before noun]","ex":{"en":"a moment of blessed calm","cn":"片刻愉快的宁静"}},{"en":"used to express mild anger","cn":"（表示愠怒）","g":"[only before noun]","lab":"old-fashioned, informal，，","ex":{"en":"I can't see a blessed thing without my glasses.","cn":"我不戴眼镜根本看不清什么东西。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"拥有…的；享有…的","en":"If someone is blessed with a particular good quality or skill, they have that good quality or skill.","ex":{"en":"Both are blessed with uncommon ability to fix things.","cn":"两人在修理东西上都有一手绝活。"}},{"pos":"ADJ 形容词","cn":"令人快乐的；可喜的；美好的","en":"You use blessed to describe something that you think is wonderful, and that you are grateful for or relieved about.","ex":{"en":"The birth of a live healthy baby is a truly blessed event","cn":"一个健康活泼的婴儿的出生真是一件可喜的事情。"}},{"pos":"ADJ 形容词","cn":"（强调生气）该死的，倒霉的，讨厌的","en":"Some people use blessed to emphasize that they are annoyed about something.","ex":{"en":"No-one knows a blessed thing.","cn":"竟然没有一个人了解点儿情况。"}}]},"examples":[{"en":"I can't see a blessed thing without my glasses.","cn":"我不戴眼镜根本看不清什么东西。"},{"en":"The kitchen was warm and blessedly familiar.","cn":"厨房又温暖又亲切温馨。"}]},"blue":{"media":{"uk":"media/uk/blue__gb_1.mp3","us":"media/us/blue__us_1.mp3"},"oxford":{"phon":"bluː","pos":"adjective","senses":[{"en":"having the colour of a clear sky or the sea on a clear day","cn":"蓝色的；天蓝色的；蔚蓝色的","ex":{"en":"piercing blue eyes","cn":"锐利的蓝眼睛"}},{"en":"looking slightly blue in colour because the person is cold or cannot breathe easily","cn":"（由于冷或呼吸困难）发青的，青紫的","ex":{"en":"His lips were turning blue.","cn":"他的嘴唇发紫。"}},{"en":"sad","cn":"忧郁的；悲伤的","lab":"informal","ex":{"en":"He'd been feeling blue all week.","cn":"他整个星期都郁郁不乐。"}},{"en":"films, jokes or stories that are blue are about sex","cn":"（电影、玩笑或故事）色情的，黄色的","ex":{"en":"a blue movie","cn":"色情片"}},{"en":"(of an area in the US) having more people who vote for the Democratic candidate than the Republican one","cn":"（美国地区）蓝色的（支持民主党候选人多于支持共和党候选人）","lab":"politics","ex":{"en":"blue states/counties","cn":"蓝州；蓝县"}},{"en":"the colour of a clear sky or the sea on a clear day","cn":"蓝色；天蓝色；蔚蓝色","g":"[countable, uncountable]","ex":{"en":"bright/dark/light/pale/deep blue","cn":"亮／暗／浅／淡／深蓝色"},"pos":"noun"},{"en":"a person who has played a particular sport for Oxford or Cambridge University; a title given to them","cn":"蓝色荣誉者（牛津或剑桥大学的校队运动员）；蓝色荣誉的头衔","g":"[countable]","lab":"British English","ex":{"en":"He’s an Oxford rugby blue.","cn":"他是牛津蓝橄榄球队的球员。"},"pos":"noun"},{"en":"a mistake","cn":"错误；失误","g":"[countable]","lab":"Australian English, New Zealand English, informal，，，，","pos":"noun"},{"en":"a name for a person with red hair","cn":"红发人","g":"[countable]","lab":"Australian English, New Zealand English, informal，，，，","pos":"noun"},{"en":"a fight","cn":"打架；打斗；斗殴","g":"[countable]","lab":"Australian English, New Zealand English, informal，，，，","pos":"noun"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"蓝色；天蓝色","en":"Something that is blue is the colour of the sky on a sunny day.","ex":{"en":"There were swallows in the cloudless blue sky","cn":"燕子在万里无云的蓝天飞翔。"}},{"pos":"N-PLURAL 复数名词","cn":"蓝调音乐，布鲁斯音乐（源于美国南部黑人音乐家，节奏缓慢，旋律感强）","en":"The blues is a type of music which was developed by African American musicians in the southern United States. It is characterized by a slow tempo and a strong rhythm.","ex":{"en":"His singing really does have the depth and the emotional range of the blues.","cn":"他的歌声确实颇有布鲁斯音乐的内蕴和情感深度。"}},{"pos":"N-PLURAL 复数名词","cn":"忧郁；沮丧；悲伤","en":"If you have got the blues, you feel sad and depressed.","ex":{"en":"Interfering in-laws are the prime sources of the blues.","cn":"喜欢指手画脚的姻亲最让人头疼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忧郁的；沮丧的；悲伤的","en":"If you are feeling blue, you are feeling sad or depressed, often when there is no particular reason.","ex":{"en":"There's no earthly reason for me to feel so blue.","cn":"我也说不出来为什么这么沮丧。"}},{"pos":"N-COUNT 可数名词","cn":"（剑桥或牛津大学的）校队运动员，蓝色荣誉者","en":"A Cambridge blue or an Oxford blue is a man or woman who has played for Cambridge or Oxford University in a particular sport."},{"pos":"ADJ 形容词","cn":"色情的；黄色的","en":"Blue films, stories, or jokes are about sex.","ex":{"en":"...a secret stash of porn mags and blue movies.","cn":"偷偷藏起来的一堆色情杂志和黄色影碟"}},{"pos":"PHRASE 短语","cn":"突然；出乎意料地","en":"If something happens out of the blue, it happens unexpectedly.","ex":{"en":"One of them wrote to us out of the blue several years later.","cn":"数年后他们中的一人突然给我们写了一封信。"}},{"pos":"","cn":"","en":"bolt from the blue→see: ; blue moon→see: ; blue murder→see: ;"}]},"examples":[{"en":"You can argue till you're blue in the face, but you won't change my mind.","cn":"你可以费尽口舌，但改变不了我的主意。"},{"en":"The room was decorated in vibrant blues and yellows.","cn":"房间内部以鲜明的蓝色和黄色作为装饰。"}]},"blows":{"lemma":"blow"},"blow":{"oxford":{"phon":"bləʊ","pos":"verb","senses":[{"en":"to send out air from the mouth","cn":"吹","g":"[intransitive, transitive]","sc":"from mouth","ex":{"en":"You're not blowing hard enough!","cn":"你没有用劲吹！"}},{"en":"when the wind or a current of air blows, it is moving; when it blows, the wind is blowing","cn":"刮；吹","g":"[intransitive, transitive]","sc":"of wind","ex":{"en":"The birds were singing and a warm wind was blowing.","cn":"鸟儿在歌唱，温暖的风吹过。"}},{"en":"to be moved by the wind, somebody’s breath, etc.; to move something in this way","cn":"（被）刮动，吹动","g":"[intransitive, transitive]","sc":"move with wind/breath","ex":{"en":"My hat blew off.","cn":"我的帽子被风吹走了。"}},{"en":"if you blow a whistle, musical instrument, etc. or if a whistle, etc. blows, you produce a sound by blowing into the whistle, etc.","cn":"吹，吹奏（哨子、乐器等）；（哨子、乐器等）吹奏出音","g":"[transitive, intransitive]","sc":"whistle/instrument","ex":{"en":"the sound of trumpets blowing","cn":"吹喇叭的声音"}},{"en":"to clear your nose by blowing strongly through it into a tissue or handkerchief","cn":"擤（鼻子）","g":"[transitive]","sc":"your nose","ex":{"en":"She grabbed a tissue and loudly blew her nose.","cn":"她抓起了一张纸巾，大声地擤鼻子。"}},{"en":"to kiss your hand and then pretend to blow the kiss towards somebody","cn":"（向某人）送飞吻","g":"[transitive]","sc":"a kiss"},{"en":"to make or shape something by blowing","cn":"吹出（某物）；把（某物）吹出形状","g":"[transitive]","sc":"shape something","ex":{"en":"to blow smoke rings","cn":"吐烟圈"}},{"en":"if a fuse blows or you blow a fuse, the electricity stops flowing suddenly because the fuse (= a thin wire) has melted because the current was too strong","cn":"（使保险丝）熔化，烧断","g":"[intransitive, transitive]","sc":"electricity"},{"en":"to break open or apart, especially because of pressure from inside; to make a tyre break in this way","cn":"破裂；爆裂；爆胎","g":"[intransitive, transitive]","sc":"tyre","ex":{"en":"The car spun out of control when a tyre blew.","cn":"车胎爆了一个，车随后失去了控制。"}},{"en":"to break something open with explosives","cn":"炸开","g":"[transitive]","sc":"with explosives","ex":{"en":"The safe had been blown by the thieves.","cn":"保险柜被窃贼炸开了。"}},{"en":"to make known something that was secret","cn":"泄露；暴露","g":"[transitive]","lab":"informal","sc":"secret","ex":{"en":"One mistake could blow your cover (= make your real name, job, intentions, etc. known).","cn":"一不小心就会让你暴露身份。"}},{"en":"to spend or waste a lot of money on something","cn":"（在某事物上）花大钱，挥霍","g":"[transitive]","lab":"informal","sc":"money","ex":{"en":"He inherited over a million dollars and blew it all on drink and gambling.","cn":"他继承了一百多万美元，全部挥霍在饮酒和赌博上了。"}},{"en":"to waste an opportunity","cn":"浪费（机会）","g":"[transitive]","lab":"informal","sc":"opportunity","ex":{"en":"She blew her chances by arriving late for the interview.","cn":"她面试时迟到，结果错过了机会。"}},{"en":"used to show that you are annoyed, surprised or do not care about something","cn":"（表示生气、吃惊或不在乎）","g":"[transitive]","lab":"British English, informal，，","sc":"exclamation","ex":{"en":"Blow it! We've missed the bus.","cn":"真该死！我们错过了公交车。"}},{"en":"to leave a place suddenly","cn":"突然离开（某地）","g":"[transitive, intransitive]","lab":"North American English, informal，，","sc":"leave suddenly","ex":{"en":"Let's blow this joint.","cn":"咱们马上离开这家酒吧。"}},{"en":"a hard hit with the hand, a weapon, etc.","cn":"（用手、武器等的）猛击","ex":{"en":"She received a severe blow on the head.","cn":"她头上挨了重重的一击。"},"pos":"noun"},{"en":"a sudden event that hurts or damages somebody/something, causing the people affected to be sad or disappointed","cn":"（突然的）打击，伤害","ex":{"en":"Losing his job came as a terrible blow to him.","cn":"失业给他造成了沉重的打击。"},"pos":"noun"},{"en":"the action of blowing","cn":"吹；擤","ex":{"en":"Give your nose a good blow (= clear it completely).","cn":"把你的鼻子擤干净。"},"pos":"noun"},{"en":"used to show that you are annoyed about something","cn":"（表示恼火）","ex":{"en":"Blow! I completely forgot it.","cn":"哎呀！我给忘得一干二净了。"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（风）吹，刮","en":"When a wind or breeze blows, the air moves.","ex":{"en":"A chill wind blew at the top of the hill","cn":"山顶寒风呼啸。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（风）把…吹到；吹到，吹向","en":"If the wind blows something somewhere or if it blows there, the wind moves it there.","ex":{"en":"The wind blew her hair back from her forehead","cn":"风把她前额上的头发吹到了后面。"}},{"pos":"VERB 动词","cn":"吹气；呼气","en":"If you blow, you send out a stream of air from your mouth.","ex":{"en":"Danny rubbed his arms and blew on his fingers to warm them","cn":"丹尼搓着胳膊并向手指上哈气取暖。"}},{"pos":"VERB 动词","cn":"（用嘴）吹，把…吹到","en":"If you blow something somewhere, you move it by sending out a stream of air from your mouth.","ex":{"en":"He picked up his mug and blew off the steam.","cn":"他端起杯子，吹走了热气。"}},{"pos":"VERB 动词","cn":"吹，吐（泡泡、烟圈等）","en":"If you blow bubbles or smoke rings, you make them by blowing air out of your mouth through liquid or smoke.","ex":{"en":"He blew a ring of blue smoke.","cn":"他吐出了蓝色的烟圈。"}},{"pos":"V-ERG 及物/不及物动词","cn":"吹奏；吹响；鸣响","en":"When a whistle or horn blows or someone blows it, they make a sound by blowing into it.","ex":{"en":"The whistle blew and the train slid forward","cn":"汽笛鸣响，火车向前滑动。"}},{"pos":"VERB 动词","cn":"擤（鼻子）","en":"When you blow your nose, you force air out of it through your nostrils in order to clear it.","ex":{"en":"He took out a handkerchief and blew his nose.","cn":"他掏出一块手帕，擤了擤鼻子。"}},{"pos":"VERB 动词","cn":"炸飞；炸毁","en":"To blow something out ,off, or away means to remove or destroy it violently with an explosion.","ex":{"en":"The can exploded, wrecking the kitchen and bathroom and blowing out windows","cn":"罐子爆炸了，不但炸毁了厨房和浴室，还把窗户炸飞了。"}},{"pos":"VERB 动词","cn":"导致；致使","en":"If you say that something blows an event, situation, or argument into a particular extreme state, especially an uncertain or unpleasant state, you mean that it causes it to be in that state.","ex":{"en":"The dramatic World Motor Sports Council meeting in Paris blew the championship wide open as Schumacher was also docked six points","cn":"在巴黎召开的令人瞩目的世界汽车运动理事会会议使冠军归属充满各种可能，因为舒马赫也被扣了6分。"}},{"pos":"VERB 动词","cn":"挥霍；乱花","en":"If you blow a large amount of money, you spend it quickly on luxuries.","ex":{"en":"Before you blow it all on a luxury cruise, give a little thought to the future","cn":"在把钱全砸到一趟海上豪华游之前，多少考虑一下日后怎么办。"}},{"pos":"VERB 动词","cn":"失去，断送（机会）；搞砸（努力）","en":"If you blow a chance or attempt to do something, you make a mistake which wastes the chance or causes the attempt to fail.","ex":{"en":"He has almost certainly blown his chance of touring India this winter.","cn":"他几乎肯定失去了今冬去印度旅行的机会。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（保险丝）烧断；使（保险丝）熔断","en":"If a fuse blows or if something blows it, the fuse melts because too much electricity has been sent through it, and the electrical current is cut off.","ex":{"en":"The fuse blew as he pressed the button.","cn":"他刚一按下按钮，保险丝就烧断了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（轮胎）爆裂；使（轮胎）爆裂","en":"If you blow a tyre or if it blows, a hole suddenly appears in it and all the air comes out of it.","ex":{"en":"A lorry blew a tyre and careered into them","cn":"一辆货车爆胎了，向他们猛撞了过去。"}},{"pos":"PHRASE 短语","cn":"自我炫耀；自吹自擂","en":"If you blow your own trumpet or blow your own horn, you tell people that you are very clever or successful.","ex":{"en":"Hollywood cameramen have good reason to blow their own trumpets.","cn":"好莱坞的摄影师们有足够的理由可以自我吹嘘。"}},{"pos":"See also:","cn":"","en":"→see: ; to blow someone's cover→see: ; to blow hot and cold→see: ; to blow a kiss→see: ; to blow a raspberry→see: ; to blow your top→see: ; to blow the whistle→see: ;"},{"pos":"","cn":"","en":"相关词组：blow away blow out blow over blow up"},{"pos":"N-COUNT 可数名词","cn":"重击；猛击","en":"If someone receives a blow, they are hit with a fist or weapon.","ex":{"en":"He went off to hospital after a blow to the face.","cn":"他脸部受到重击之后就去了医院。"}},{"pos":"N-COUNT 可数名词","cn":"打击；挫折","en":"If something that happens is a blow to someone or something, it is very upsetting, disappointing, or damaging to them.","ex":{"en":"When the marriage finally broke up it was obviously a terrible blow to Soames","cn":"婚姻的最终破裂对索姆斯显然是一个沉重打击。"}},{"pos":"PHRASE 短语","cn":"激烈争吵；动武；打架","en":"If two people or groups come to blows, they start fighting.","ex":{"en":"The representatives almost came to blows at a meeting.","cn":"代表们在一次会议上差点动起手来。"}},{"pos":"PHRASE 短语","cn":"减轻，缓和，缓解（打击等）","en":"Something that softens the blow or cushions the blow makes an unpleasant change or piece of news easier to accept.","ex":{"en":"Senator Sarbanes expressed concern that programs designed to soften the blow of unemployment are not working well.","cn":"旨在缓解失业冲击的项目进展得并不太顺利，参议员萨班斯对此表示关切。"}},{"pos":"PHRASE 短语","cn":"支持；拥护；为…而战","en":"If you strike a blow for a particular cause or principle, you do something that supports it or makes it more likely to succeed.","ex":{"en":"The team struck a blow for women's rights by winning the match.","cn":"这个小组在比赛中获胜，维护了女性的权利。"}}]},"media":{"uk":"media/uk/blow__gb_1.mp3","us":"media/us/blow__us_1.mp3"},"examples":[{"en":"A DVD music system plays discs that look like CDs, but blows them out of the water. * DVD","cn":"音乐播放机里放的碟片看似 CD，却要比 CD 强多了。"},{"en":"What we discovered blew apart all our preconceptions about this fascinating species.","cn":"我们的发现将我们对这一奇妙物种的先入之见全盘推翻了。"}]},"blonde":{"media":{"uk":"media/uk/blonde__gb_1.mp3","us":"media/us/blonde__us_1.mp3"},"oxford":{"phon":"blɒnd","pos":"adjective","senses":[{"en":"pale gold in colour","cn":"金黄色的","ex":{"en":"She had long blonde hair.","cn":"她有一头金色长发。"}},{"en":"having blonde hair","cn":"头发金黄的","ex":{"en":"a small, blond boy","cn":"一个金发小男孩"}},{"en":"a person, especially a woman, with hair that is pale gold in colour","cn":"金发女郎","ex":{"en":"Is she a natural blonde (= Is her hair naturally blonde)?","cn":"她的头发原本就是金黄色吗？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"（头发）金色，浅棕色，浅黄色","en":"A woman who has blonde hair has pale-coloured hair. Blonde hair can be very light brown or light yellow. The form blond is used when describing men.","ex":{"en":"There were two little girls, one Asian and one with blonde hair","cn":"那里有两个小女孩，一个是亚洲女孩，一个是金发女孩。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"金发的；浅色头发的","en":"Someone who is blonde has blonde hair.","ex":{"en":"She was tall, blonde, and attractive","cn":"她个子高挑，一头金发，非常迷人。"}},{"pos":"N-COUNT 可数名词","cn":"金发女郎","en":"A blonde is a woman who has blonde hair."}]},"examples":[{"en":"Is she a natural blonde (= Is her hair naturally blonde)?","cn":"她的头发原本就是金黄色吗？"},{"en":"a small, blond boy","cn":"一个金发小男孩"}]},"blues":{"oxford":{"phon":"bluːz","pos":"noun","senses":[{"en":"a type of slow sad music with strong rhythms, developed by African American musicians in the southern US","cn":"布鲁斯音乐，蓝调（源于美国南部黑人，节奏感强、缓慢忧郁）","g":"[uncountable]","ex":{"en":"a blues band/singer","cn":"布鲁斯乐队／歌手"}},{"en":"a blues song","cn":"布鲁斯歌曲；蓝调歌曲","g":"[countable]"},{"en":"sad feelings","cn":"忧郁；悲伤；沮丧","g":"[plural]","lab":"informal","ex":{"en":"the Monday morning blues","cn":"星期一早晨的郁闷情绪"}}]},"media":{"uk":"media/uk/blues__gb_1.mp3","us":"media/us/blues__us_1.mp3"},"examples":[{"en":"the Monday morning blues","cn":"星期一早晨的郁闷情绪"},{"en":"a blues band/singer","cn":"布鲁斯乐队/歌手"}],"base":"blue"},"blackness":{"media":{"uk":"media/uk/blackness__gb_1.mp3","us":"media/us/blackness__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"漆黑；黑暗","en":"Blackness is the state of being very dark.","ex":{"en":"The twilight had turned to a deep blackness.","cn":"暮色渐浓，变成了漆黑一片。"}}]},"examples":[{"en":"She peered out into the blackness of the night.","cn":"她凝视着外面黑沉沉的夜色。"},{"en":"It was still pitch black (= very dark ) out.","cn":""}],"oxford":{"phon":"ˈblæknəs","pos":"noun","senses":[{"en":"the fact of being completely dark or completely black in colour","cn":"黑色：完全暗或完全黑色","g":"[uncountable, singular]","ex":{"en":"She peered out into the blackness of the night.","cn":"她望着外面漆黑的夜晚。"}},{"en":"the fact of being full of anger or hate or of being without hope","cn":"黑色：充满愤怒或仇恨或没有希望","g":"[uncountable]","ex":{"en":"the utter blackness of despair","cn":"绝望的彻底黑暗"}},{"en":"the fact of belonging to a group of people who have dark skin and who come from or whose ancestors came from Africa","cn":"黑色人种的人；黑人","g":"[uncountable]","ex":{"en":"complex notions of blackness","cn":"复杂的黑人概念"}}]}},"blocked":{"lemma":"block","media":{"img":["media/pic/homes_comp.jpg","media/thumb/flat.jpg"],"uk":"media/uk/block__gb_1.mp3","us":"media/us/block__us_1.mp3"}},"blunders":{"lemma":"blunder"},"blunter":{"lemma":"blunt"},"blushing":{"lemma":"blush"},"blankets":{"lemma":"blanket"},"blond":{"lemma":"blonde","media":{"uk":"media/ldoce/hwd/bre/5/blond0205.mp3","us":"media/ldoce/hwd/ame/e/blond1.mp3"}},"blocks":{"lemma":"block"},"blushes":{"lemma":"blush"},"blocking":{"lemma":"block"},"blades":{"lemma":"blade"},"blister":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（皮肤上因烫伤或反复摩擦而起的）水疱","en":"A blister is a painful swelling on the surface of your skin. Blisters contain a clear liquid and are usually caused by heat or by something repeatedly rubbing your skin."},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（皮肤）长水疱","en":"When your skin blisters or when something blisters it, blisters appear on it.","ex":{"en":"The affected skin turns red and may blister","cn":"受感染的皮肤会变红，还有可能起水疱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mark on your skin that spoils its appearance","cn":""},{"en":"a small dark, sometimes raised, mark on your skin","cn":""},{"en":"small light brown marks on your skin, especially on your face but also on your arms, shoulders etc","cn":""}]},"collocations":{"phrases":["ADV. badly Her feet were badly blistered."]},"media":{"uk":"media/ldoce/hwd/bre/0/blister_v0205.mp3","us":"media/ldoce/hwd/ame/b/blister1.mp3"},"examples":[{"en":"Her face had been blistered by the sun.","cn":"她的脸让太阳晒起水疱了。"},{"en":"His skin was beginning to blister.","cn":"他的皮肤开始起疱。"}],"oxford":{"phon":"ˈblɪstə(r)","pos":"noun","senses":[{"en":"a swelling (= an area that is larger and rounder than normal) on the surface of the skin that is filled with liquid and is caused, for example, by rubbing or burning","cn":"（皮肤上因摩擦或烧灼等引起的）水疱，疱","ex":{"en":"These shoes have given me blisters on my heels.","cn":"这双鞋让我的脚后跟起了水泡。"}},{"en":"a similar swelling, filled with air or liquid, on metal, painted wood or another surface","cn":"（金属、油漆过的木头或其他表面上的）泡，气泡，水泡"},{"en":"to form blisters; to make something form blisters","cn":"（使）起疱，起泡","g":"[intransitive, transitive]","ex":{"en":"His skin was beginning to blister.","cn":"他的皮肤开始起疱。"},"pos":"verb"},{"en":"when a surface blisters or something blisters it, it becomes covered with round areas that are filled with air or liquid and break open","cn":"（使表皮等）涨破，爆裂","g":"[intransitive, transitive]","pos":"verb"},{"en":"to criticize somebody strongly","cn":"猛烈抨击；严厉批评","g":"[transitive]","lab":"North American English","pos":"verb"}]}},"blasphemous":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"亵渎神明（或宗教）的","en":"You can describe someone who shows disrespect for God or a religion as blasphemous. You can also describe what they are saying or doing as blasphemous .","ex":{"en":"She was accused of being blasphemous","cn":"她被控亵渎神明。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something you say or do that is insulting to God or people’s religious beliefs","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Blasphemous is an adjective that describes profane words and actions, especially when they are connected to something religious. If you draw Jesus Christ wearing lipstick or call Buddha a fat slob, you're displaying blasphemous behavior."}]},"collocations":{"phrases":["VERBS be, seem | consider sth | declare sth, deem sth The book was declared blasphemous and all copies ordered to be burnt.","ADV. almost"]},"media":{"uk":"media/ldoce/hwd/bre/e/blasphemy0205.mp3","us":"media/ldoce/hwd/ame/2/blasphemy.mp3"},"examples":[{"en":"Many people found the film blasphemous.","cn":"很多人觉得那部电影亵渎了神灵。"}],"oxford":{"phon":"ˈblæsfəməs","pos":"adjective","senses":[{"en":"showing a lack of respect for God or religion","cn":"亵渎的;侮慢的;不敬的","ex":{"en":"Many people found the film blasphemous.","cn":"许多人觉得这部电影亵渎了上帝。"}}]}},"blizzard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大风雪；暴风雪","en":"A blizzard is a very bad snowstorm with strong winds."},{"pos":"N-COUNT 可数名词","cn":"（指令人反感或恼火的事情）大量，铺天盖地","en":"You can refer to a large number of things that you do not like or which annoy you as a blizzard of those things.","ex":{"en":"Retailers were hit with a blizzard of new products and brands in all shapes, sizes and colours.","cn":"各种形色不一、大小各异的新产品和新品牌铺天盖地，让零售商们疲于应付。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of very bad weather when there is a lot of rain or snow, strong winds, and often lightning","cn":""},{"en":"a storm in which there is a lot of thunder (= loud noise in the sky ) and lightning (= flashes of light in the sky )","cn":""},{"en":"a storm that has very strong fast winds and that moves over water – used about storms in the North Atlantic Ocean","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A blizzard is a large winter storm, characterized by heavy snowfall and accompanied by high winds. We're not talking flurry or a snowsquall . It's the kind of snow storm you read about."}]},"collocations":{"phrases":["ADJ. fierce, howling","VERB + BLIZZARD blow After a short while it began to blow a blizzard.","BLIZZARD + VERB hit (sth), strike (sth) The blizzard struck while we were still on the mountain. | blow, rage","BLIZZARD + NOUN conditions","PREP. in/into ~ We got stuck in a howling blizzard. | through ~ He fought his way through the blizzard."]},"media":{"uk":"media/ldoce/hwd/bre/d/blizzard0205.mp3","us":"media/ldoce/hwd/ame/7/blizzard.mp3"},"examples":[{"en":"a raging/howling blizzard","cn":"猛烈的/怒吼着的暴风雪"},{"en":"a blizzard of documents","cn":"一大堆棘手的文件"}],"oxford":{"phon":"ˈblɪzəd","pos":"noun","senses":[{"en":"a snowstorm with very strong winds","cn":"暴风雪；雪暴","lab":"North American English","ex":{"en":"blizzard conditions","cn":"暴风雪天气"}},{"en":"a large quantity of things that may seem to be attacking you","cn":"大批侵扰性的事物；大量的负担","ex":{"en":"a blizzard of documents","cn":"一大堆棘手的文件"}}]}},"blacklist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"黑名单","en":"If someone is on a blacklist, they are seen by a government or other organization as being one of a number of people who cannot be trusted or who have done something wrong.","ex":{"en":"A government official disclosed that they were on a secret blacklist","cn":"一名政府官员透露他们已被列入一份秘密黑名单。"}},{"pos":"VERB 动词","cn":"把…列入黑名单","en":"If someone is blacklisted by a government or organization, they are put on a blacklist.","ex":{"en":"He has been blacklisted since being convicted of possessing marijuana in 1969.","cn":"他自从1969年因持有大麻而被定罪后就被列入了黑名单。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that someone must not do something, and stop them doing it. Not allow is more formal than not let","cn":""},{"en":"to tell someone that they should not do something, especially because it is dangerous or harmful","cn":""},{"en":"to say clearly and strongly that someone should not do something","cn":""}]},"collocations":{"phrases":["VERB + BLACKLIST place sb on, put sb on | draw up","PREP. on a/the ~ She was on the company's blacklist."]},"media":{"uk":"media/ldoce/hwd/bre/3/blacklist_v0205.mp3","us":"media/ldoce/hwd/ame/6/blacklist.mp3"},"examples":[{"en":"She was blacklisted by all the major Hollywood studios because of her political views.","cn":"由于她的政见，所有好莱坞大制片公司都拒绝用她。"},{"en":"Many people in the industry were blacklisted for their communist sympathies.","cn":"行业里有许多人因为同情共产党而被列入了黑名单。"}],"oxford":{"phon":"ˈblæklɪst","pos":"noun","senses":[{"en":"a list of the names of people, companies, products or countries that an organization or a government considers unacceptable and that must be avoided","cn":"黑名单","ex":{"en":"a blacklist of countries where illegal copying of software is thought to be widespread","cn":"盛行非法复制软件的国家黑名单"}},{"en":"to put the name of a person, a company, a product or a country on a blacklist","cn":"将…列入黑名单","ex":{"en":"She was blacklisted by all the major Hollywood studios because of her political views.","cn":"由于她的政见，所有好莱坞大制片公司都拒绝用她。"},"pos":"verb"}]}},"bloom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"花；花朵","en":"A bloom is the flower on a plant.","ex":{"en":"...the sweet fragrance of the white blooms","cn":"白色花朵的芳香"}},{"pos":"PHRASE 短语","cn":"正开花的；花朵绽放的","en":"A plant or tree that is in bloom has flowers on it.","ex":{"en":"...a pink climbing rose in full bloom.","cn":"盛开的粉色藤蔓玫瑰"}},{"pos":"VERB 动词","cn":"开花；（花朵）绽放","en":"When a plant or tree blooms, it produces flowers. When a flower blooms, it opens.","ex":{"en":"This plant blooms between May and June.","cn":"这种植物在5月至6月间开花。"}},{"pos":"VERB 动词","cn":"繁荣；兴盛；茁壮成长；变漂亮","en":"If someone or something blooms, they develop good, attractive, or successful qualities.","ex":{"en":"Not many economies bloomed in 1990, least of all gold exporters like Australia","cn":"1990年经济繁荣的国家并不多，尤其是像澳大利亚这样的黄金出口国。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（肤色的）红润，健康的光彩；容光","en":"If something such as someone's skin has a bloom, it has a fresh and healthy appearance.","ex":{"en":"The skin loses its youthful bloom.","cn":"皮肤失去了年轻时的光泽。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flower or flowers","cn":"花"},{"en":"with the flowers fully open 〔","cn":"鲜花〕盛开﹐怒放"},{"en":"the healthy happy appearance that someone has, especially when they are young","cn":"健康的气色〔尤指人年轻时〕"}]},"vocab":{"pos":"1 v n 2 n 3 n","senses":[{"en":"A bloom is a flower. You might mark the beginning of spring by the very first bloom you see in your garden."}]},"collocations":{"phrases":["ADJ. beautiful, exquisite, perfect a tree with exquisite blooms | fragrant | exotic","VERB + BLOOM bear, have, produce | burst into, come into The spring flowers have come into bloom.","BLOOM + VERB appear The small white blooms appear in May. | fade The blooms have started to fade now.","PREP. in ~ banks of rhododendrons in bloom","PHRASES in full bloom The roses are now in full bloom."]},"media":{"uk":"media/ldoce/hwd/bre/8/bloom_n0205.mp3","us":"media/ldoce/hwd/ame/1/bloom1.mp3"},"examples":[{"en":"The children had bloomed during their stay on the farm.","cn":"孩子们在农场期间健康活泼有生气。"},{"en":"Most roses will begin to bloom from late May.","cn":"大多数玫瑰从五月末开始开花。"}],"oxford":{"phon":"bluːm","pos":"noun","senses":[{"en":"a flower (usually one on a plant that people admire for its flowers)","cn":"（常指供观赏的）花","g":"[countable]","lab":"formal or specialist","ex":{"en":"the exotic blooms of the orchid","cn":"奇异的兰花"}},{"en":"a healthy fresh appearance","cn":"健康有精神的面貌","g":"[singular, uncountable]","ex":{"en":"the bloom in her cheeks","cn":"她面颊上的红润光泽"}},{"en":"to produce flowers","cn":"开花","g":"[intransitive]","ex":{"en":"Most roses will begin to bloom from late May.","cn":"大多数玫瑰从五月末开始开花。"},"pos":"verb"},{"en":"to become healthy, happy or confident","cn":"变得健康（或快活、自信）","g":"[intransitive]","ex":{"en":"The children had bloomed during their stay on the farm.","cn":"孩子们在农场期间健康活泼有生气。"},"pos":"verb"}]}},"blackmail":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"勒索；敲诈；讹诈","en":"Blackmail is the action of threatening to reveal a secret about someone, unless they do something you tell them to do, such as giving you money.","ex":{"en":"It looks like the pictures were being used for blackmail","cn":"这些照片好像被用于敲诈勒索。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（情感或道德上的）迫使，胁迫","en":"If you describe an action as emotional or moral blackmail, you disapprove of it because someone is using a person's emotions or moral values to persuade them to do something against their will.","ex":{"en":"The tactics employed can range from overt bullying to subtle emotional blackmail.","cn":"从公然威吓到微妙的情感胁迫，各种战术都用上了。"}},{"pos":"VERB 动词","cn":"勒索；敲诈；讹诈","en":"If one person blackmails another person, they use blackmail against them.","ex":{"en":"He told her their affair would have to stop, because Jack Smith was blackmailing him","cn":"他告诉她说他们的婚外情必须结束了，因为杰克·史密斯正在敲诈他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to force someone to do something that they do not want to do. Make is less formal than force","cn":""},{"en":"to keep trying to persuade someone to do something, for example by saying that it is their duty or that it will help other people","cn":""},{"en":"to try to make someone do something by persuading them very strongly and making them feel that they should do it","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"To blackmail someone is to use secret information to get something from them, usually money. Blackmailing is a crime."}]},"collocations":{"phrases":["ADV. virtually","VERB + BLACKMAIL attempt to, try to","PREP. into She says she was virtually blackmailed into giving up her claim to the property."]},"media":{"uk":"media/ldoce/hwd/bre/d/blackmail_n0205.mp3","us":"media/ldoce/hwd/ame/4/blackmail.mp3"},"examples":[{"en":"The President said he wouldn't be blackmailed into agreeing to the terrorists' demands.","cn":"总统说他不会因受恐怖分子的威胁而答应他们的要求。"},{"en":"She blackmailed him for years by threatening to tell the newspapers about their affair.","cn":"她以向报界公开他们的恋情要挟了他很多年。"}],"oxford":{"phon":"ˈblækmeɪl","pos":"noun","senses":[{"en":"the crime of demanding money from a person by threatening to tell somebody else a secret about them","cn":"勒索；敲诈"},{"en":"the act of putting pressure on a person or a group to do something they do not want to do, for example by making threats or by making them feel guilty","cn":"胁迫；威胁；恐吓","ex":{"en":"emotional/moral blackmail","cn":"情感上／道德上胁迫"}},{"en":"to force somebody to give you money or do something for you by threatening them, for example by saying you will tell people a secret about them","cn":"勒索；敲诈；要挟；胁迫","ex":{"en":"She blackmailed him for years by threatening to tell the newspapers about their affair.","cn":"她以向报界公开他们的私情要挟了他很多年。"},"pos":"verb"}]}},"blemish":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"污点；瑕疵；疤痕","en":"A blemish is a small mark on something that spoils its appearance.","ex":{"en":"Every piece is closely scrutinised, and if there is the slightest blemish on it, it is rejected.","cn":"每一件物品都经过严格检查，稍有瑕疵就会被退回。"}},{"pos":"N-COUNT 可数名词","cn":"缺点；缺陷；不足","en":"A blemish on something is a small fault in it.","ex":{"en":"This is the one blemish on an otherwise resounding success.","cn":"如果没有这个小小的失误，这就是一次彻底的胜利。"}},{"pos":"VERB 动词","cn":"玷污；损害","en":"If something blemishes someone's character or reputation, it spoils it or makes it seem less good than it was in the past.","ex":{"en":"He wasn't about to blemish that pristine record.","cn":"他本不想去玷污那清白的过去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mark on your skin that spoils its appearance","cn":""},{"en":"a small dark, sometimes raised, mark on your skin","cn":""},{"en":"small light brown marks on your skin, especially on your face but also on your arms, shoulders etc","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A blemish is a small flaw. If you borrow your brother's brand new bicycle, you'd better be careful — what might seem like the tiniest blemish to you might be a horribly ruined paint job to him."}]},"collocations":{"phrases":["ADJ. minor, slight","VERB + BLEMISH have The police say the suspect has a slight blemish on his left cheek.","PREP. without (a) ~ (figurative) He was pilloried, but she escaped without blemish."]},"media":{"uk":"media/ldoce/hwd/bre/0/blemish_n0205.mp3","us":"media/ldoce/hwd/ame/a/blemish1.mp3"},"examples":[{"en":"( figurative ) His reputation is without a blemish.","cn":"他的名誉可说是白璧无瑕。"},{"en":"His reputation is without a blemish.","cn":""}],"oxford":{"phon":"ˈblemɪʃ","pos":"noun","senses":[{"en":"a mark on the skin or on an object that makes it look less beautiful or perfect","cn":"斑点；疤痕；瑕疵","lab":"figurative","ex":{"en":"make-up to cover blemishes","cn":"遮盖霜"}},{"en":"to make something less beautiful or perfect","cn":"破坏…完美；玷污","pos":"verb"}]}},"bloodstream":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"血流；血液","en":"Your bloodstream is the blood that flows around your body.","ex":{"en":"The disease releases toxins into the bloodstream.","cn":"这种病会释放毒素到血液中。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the blood flowing in your body","cn":"体内循环的血液﹐血流"}]},"collocations":{"phrases":["VERB + BLOODSTREAM enter | absorb sth into The drug is quickly absorbed into the bloodstream.","PREP. in sb's/the ~ Traces of banned substances were detected in his bloodstream. | into sb's/the ~ Bacteria was introduced into his bloodst"]},"media":{"uk":"media/ldoce/hwd/bre/3/bloodstream0205.mp3","us":"media/ldoce/hwd/ame/b/bloodstream.mp3"},"examples":[{"en":"They injected the drug directly into her bloodstream.","cn":"他们把麻醉剂直接注射到她的血液里。"},{"en":"The drug is injected directly into the bloodstream.","cn":"这种药物直接注射到血液中。"}],"oxford":{"phon":"ˈblʌdstriːm","pos":"noun","senses":[{"en":"the blood flowing through the body","cn":"体内循环的血液；血流","ex":{"en":"They injected the drug directly into her bloodstream.","cn":"他们把药物直接注射到她的血液里。"}}]}},"bliss":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"巨大的幸福；极乐","en":"Bliss is a state of complete happiness.","ex":{"en":"It was a scene of such domestic bliss.","cn":"这是一派天伦之乐的场景。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of great happiness","cn":""},{"en":"the feeling you have when you are very pleased and excited because something good has happened","cn":""},{"en":"a feeling of very great happiness and great pleasure – used when something has a great effect on your senses","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Bliss is a state of complete happiness or joy. Marriage is often associated with this joyous feeling: people who are married and still in love are described as living in wedded bliss ."}]},"collocations":{"phrases":["ADJ. sheer The first six months of marriage were sheer bliss. | domestic | marital, married, wedded They're celebrating 25 years of wedded b","PHRASES sb's idea of bliss My idea of bliss is a hot day and an ice-cold beer."]},"media":{"uk":"media/ldoce/hwd/bre/5/bliss0205.mp3","us":"media/ldoce/hwd/ame/1/bliss.mp3"},"examples":[{"en":"My idea of bliss is a month in the Bahamas.","cn":"我理想中的极乐是在巴哈马群岛度假一个月。"},{"en":"Swimming on a hot day is sheer bliss.","cn":"热天游泳是天大的乐事。"}],"oxford":{"phon":"blɪs","pos":"noun","senses":[{"en":"extreme happiness","cn":"极乐","ex":{"en":"married/wedded/domestic bliss","cn":"婚后的／家庭的幸福"}}]}},"bleed":{"collins":{"senses":[{"pos":"VERB 动词","cn":"出血；流血","en":"When you bleed, you lose blood from your body as a result of injury or illness.","ex":{"en":"His head had struck the sink and was bleeding","cn":"他的头撞到了水槽上，正在流血。"}},{"pos":"VERB 动词","cn":"（颜色）渗开，弥散","en":"If the colour of one substance bleeds into the colour of another substance that it is touching, it goes into the other thing so that its colour changes in an undesirable way.","ex":{"en":"The colouring pigments from the skins are not allowed to bleed into the grape juice.","cn":"外皮上的色素不能渗到葡萄汁里面去。"}},{"pos":"VERB 动词","cn":"逐渐榨取…的钱财","en":"If someone is being bled, money or other resources are gradually being taken away from them.","ex":{"en":"We have been gradually bled for twelve years","cn":"我们被一点一滴地压榨了12年。"}},{"pos":"PHRASE 短语","cn":"榨干…的钱财（或资源）","en":"If someone is being bled dry or is being bled white, all of their money or other resources are gradually being taken away from them.","ex":{"en":"The war has bled the once-strong Armenian economy dry.","cn":"战争榨干了原本繁荣的亚美尼亚经济。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you hurt a part of your body, you accidentally damage it so that it feels painful or you cannot move it easily","cn":""},{"en":"to hurt a part of your body, especially seriously and in a way that takes a long time to get better","cn":""},{"en":"to hurt a part of your body when you fall or hit it against something, causing a dark, painful mark to form on your skin","cn":""}]},"collocations":{"phrases":["ADV. badly, heavily, profusely | easily The small blood vessels in the nose bleed easily.","PREP. from She was bleeding heavily from a head wound.","PHRASES bleed to death"]},"media":{"uk":"media/ldoce/hwd/bre/2/bleed0205.mp3","us":"media/ldoce/hwd/ame/0/bleed.mp3"},"examples":[{"en":"Keep the paint fairly dry so that the colours don't bleed into each other.","cn":"涂料尽量干一些，以免颜色相互渗透。"},{"en":"My ex-wife is bleeding me for every penny I have.","cn":"我的前妻不断地榨取我的每一分钱。"}],"oxford":{"phon":"bliːd","pos":"verb","senses":[{"en":"to lose blood, especially from a wound or an injury","cn":"流血；失血","g":"[intransitive]","ex":{"en":"My finger's bleeding.","cn":"我的手指出血了。"}},{"en":"(in the past) to take blood from somebody as a way of treating disease","cn":"（旧时）给（某人）放血","g":"[transitive]"},{"en":"to force somebody to pay a lot of money over a period of time","cn":"长期榨取（某人的钱）","g":"[transitive]","lab":"informal","ex":{"en":"The company seems intent on bleeding us for every penny we have.","cn":"这间公司似乎存心要榨干我们的每一分钱。"}},{"en":"to remove air or liquid from something so that it works correctly","cn":"放掉气体或水（以使某物运行正常）；抽干","g":"[transitive]"},{"en":"to spread from one area of something to another area","cn":"散开；渗开","g":"[intransitive]","ex":{"en":"Keep the paint fairly dry so that the colours don't bleed into each other.","cn":"涂料尽量干一些，以免颜色相互渗透。"}}]}},"bloodshed":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"流血事件；杀戮","en":"Bloodshed is violence in which people are killed or wounded.","ex":{"en":"The government must increase the pace of reforms to avoid further bloodshed.","cn":"政府必须加快改革步伐，避免发生更多的流血事件。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the killing of people, usually in fighting or war","cn":"流血事件﹐杀戮﹐残杀"}]},"collocations":{"phrases":["ADJ. further | massive, widespread","VERB + BLOODSHED cause, end in, lead to This election result could well lead to further bloodshed. | end, halt, stop | avoid, prevent"]},"media":{"uk":"media/ldoce/hwd/bre/b/bloodshed0205.mp3","us":"media/ldoce/hwd/ame/4/bloodshed.mp3"},"examples":[{"en":"The two sides called a truce to avoid further bloodshed.","cn":"双方宣布休战，以免再有人员伤亡。"},{"en":"diplomacy aimed at stopping further bloodshed","cn":"旨在阻止流血事件再次发生的外交活动"}],"oxford":{"phon":"ˈblʌdʃed","pos":"noun","senses":[{"en":"the killing or wounding of people, usually during fighting or a war","cn":"（战斗或战争中的）人员伤亡，流血事件","ex":{"en":"The two sides called a truce to avoid further bloodshed.","cn":"双方宣布休战，以免再有人员伤亡。"}}]}},"blunder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"愚蠢的错误；疏忽；失误","en":"A blunder is a stupid or careless mistake.","ex":{"en":"I think he made a tactical blunder by announcing it so far ahead of time.","cn":"我认为他在时机远未成熟时就把这事说了出去是一种失策。"}},{"pos":"VERB 动词","cn":"犯愚蠢的错误；失误","en":"If you blunder, you make a stupid or careless mistake.","ex":{"en":"No doubt I had blundered again","cn":"无疑，我又犯了一个愚蠢的错误。"}},{"pos":"VERB 动词","cn":"不慎陷入，误打误撞地进入（危险或困难的境地）","en":"If you blunder into a dangerous or difficult situation, you get involved in it by mistake.","ex":{"en":"People wanted to know how they had blundered into war, and how to avoid it in future.","cn":"人们想知道他们是怎样稀里糊涂地陷入战争的，以及日后该如何避免重蹈覆辙。"}},{"pos":"VERB 动词","cn":"跌跌撞撞；慌乱地走","en":"If you blunder somewhere, you move there in a clumsy and careless way.","ex":{"en":"He had blundered into the table, upsetting the flowers.","cn":"他不小心撞到了桌子，把花打翻了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a stupid mistake caused by not thinking carefully enough about what you are saying or doing, which could have serious results","cn":""},{"en":"an embarrassing and stupid mistake made in a social situation or in public","cn":""},{"en":"a very bad mistake, especially one that shows you do not know something, and that often makes other people laugh","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A blunder is an embarrassing mistake. Accidentally called your new boyfriend by your old boyfriend's name? Ouch. That's a blunder you don't want to repeat."}]},"collocations":{"phrases":["ADJ. big, major | stupid | fatal, terrible, tragic | tactical | administrative, bureaucratic, economic, political","QUANT. series","VERB + BLUNDER commit, make The minister has made a series of political blunders."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdeblunder.mp3","us":"media/ldoce/hwd/ame/f/blunder1.mp3"},"examples":[{"en":"The government had blundered in its handling of the affair.","cn":"政府在这件事的处理上犯了大错。"},{"en":"a series of political blunders","cn":"一连串政治失误"}],"oxford":{"phon":"ˈblʌndə(r)","pos":"noun","senses":[{"en":"a stupid or careless mistake","cn":"愚蠢（或粗心）的错误","ex":{"en":"to make a terrible blunder","cn":"犯大错"}},{"en":"to make a stupid or careless mistake","cn":"犯愚蠢的（或粗心的）错误","ex":{"en":"The government had blundered in its handling of the affair.","cn":"政府在这件事的处理上犯了大错。"},"pos":"verb"}]}},"bloke":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"人；家伙","en":"A bloke is a man.","ex":{"en":"He is a really nice bloke.","cn":"他真是个好人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man","cn":"男人﹐家伙"}]},"collocations":{"phrases":["ADJ. decent, good, great, lovely, nice | average, ordinary He's an ordinary bloke, despite being famous. | funny He's a funny bloke?you neve","PHRASES the kind/sort/type of bloke He's the sort of bloke who will never let you down."]},"media":{"uk":"media/ldoce/hwd/bre/6/bloke0205.mp3","us":"media/ldoce/hwd/ame/2/bloke.mp3"},"examples":[{"en":"He seemed like a nice bloke.","cn":"他看上去像个好人。"},{"en":"He’s a nice bloke.","cn":"他这人不错。"}],"oxford":{"phon":"bləʊk","pos":"noun","senses":[{"en":"a man","cn":"男人；家伙","ex":{"en":"He seemed like a nice bloke.","cn":"他看上去像个好人。"}}]}},"blasphemy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"亵渎上帝（或宗教）的言行","en":"You can describe something that shows disrespect for God or a religion as blasphemy .","ex":{"en":"He was found guilty of blasphemy and sentenced to three years in jail","cn":"他被判犯有亵渎神明罪，刑期3年。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something you say or do that is insulting to God or people’s religious beliefs","cn":"对上帝的亵渎﹔亵渎神明的言辞[行为]"}]},"vocab":{"pos":"n","senses":[{"en":"Saying offensive things about God or religion is blasphemy . Blasphemy can be used for offensive ideas in other areas too."}]},"collocations":{"phrases":["VERB + BLASPHEMY commit","BLASPHEMY + NOUN law","PREP. ~ against His writings were branded as obscene and a blasphemy against God.","PHRASES a charge of blasphemy"]},"media":{"uk":"media/ldoce/hwd/bre/e/blasphemy0205.mp3","us":"media/ldoce/hwd/ame/2/blasphemy.mp3"},"examples":[{"en":"Many people found the film blasphemous.","cn":"很多人觉得那部电影亵渎了神灵。"}],"oxford":{"phon":"ˈblæsfəmi","pos":"noun","senses":[{"en":"behaviour or language that is offensive or shows a lack of respect for God or religion","cn":"亵渎上帝（或神明）的言行","ex":{"en":"He was accused of blasphemy.","cn":"他被指控亵渎神明。"}}]}},"blast":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"爆炸","en":"A blast is a big explosion, especially one caused by a bomb.","ex":{"en":"250 people were killed in the blast.","cn":"250人在这次爆炸中丧生。"}},{"pos":"VERB 动词","cn":"爆炸；炸毁；炸出；炸开","en":"If something is blasted into a particular place or state, an explosion causes it to be in that place or state. If a hole is blasted in something, it is created by an explosion.","ex":{"en":"There is a risk that toxic chemicals might be blasted into the atmosphere.","cn":"爆炸后有毒化学物质可能会进入大气层。"}},{"pos":"VERB 动词","cn":"炸（石）；爆破","en":"If workers are blasting rock, they are using explosives to make holes in it or destroy it, for example so that a road or tunnel can be built.","ex":{"en":"Their work was taken up with boring and blasting rock with gelignite","cn":"他们的工作是用葛里炸药炸石头，非常枯燥。"}},{"pos":"VERB 动词","cn":"枪击；开枪射击","en":"To blast someone means to shoot them with a gun.","ex":{"en":"...a son who blasted his father to death after a lifetime of bullying","cn":"因从小到大一直被父亲虐待而开枪弑父的男子"}},{"pos":"VERB 动词","cn":"（通过枪击） 冲出（道路）；轰开，炸开（通路）","en":"If someone blasts their way somewhere, they get there by shooting at people or causing an explosion.","ex":{"en":"The police were reported to have blasted their way into the house using explosives","cn":"据报道，警方借助爆破冲进了房子。"}},{"pos":"VERB 动词","cn":"喷射（水流、气流等）","en":"Ifsomething blasts water or air somewhere, it sends out a sudden, powerful stream of it.","ex":{"en":"Blasting cold air over it makes the water evaporate","cn":"向它喷射冷空气可以使水蒸发。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（汽车喇叭等）突然发出响亮的声音；（使）（音乐）轰响","en":"If you blast something such as a car horn, or if it blasts, it makes a sudden, loud sound. If something blasts music, or music blasts, the music is very loud.","ex":{"en":"...drivers who do not blast their horns","cn":"不按喇叭的司机"}},{"pos":"VERB 动词","cn":"（体育运动中）用力踢，猛击","en":"You can say that a sports player blasts the ball somewhere if he or she gives it a powerful kick or hit.","ex":{"en":"Ramsay blasted the ball into the back of the net","cn":"拉姆齐劲射入网。"}},{"pos":"VERB 动词","cn":"炮轰；抨击","en":"To blast someone or something means to criticize them strongly.","ex":{"en":"Football: Taylor blasts Beck","cn":"足球：泰勒炮轰贝克。"}},{"pos":"EXCLAM 感叹语","cn":"（表示厌恶）真讨厌,真该死","en":"Some people say 'blast' to show that they are annoyed at something or someone.","ex":{"en":"Blast! I can't do anything with this.","cn":"真该死！我拿这个一点办法也没有。"}},{"pos":"N-SING 单数名词","cn":"有趣的事；开心的事；乐趣","en":"If you say that something was a blast, you mean that you enjoyed it very much.","ex":{"en":"Making the album was a real blast.","cn":"做这个专辑真是一种乐趣。"}},{"pos":"PHRASE 短语","cn":"以最大音量；以最大功率","en":"If something such as a radio or a heater is on full blast, or at full blast, it is producing as much sound or power as it is able to.","ex":{"en":"In many of those homes the television is on full blast 24 hours a day","cn":"那些家庭有很多一天24小时把电视开到最大音量。"}},{"pos":"PHRASE 短语","cn":"岁月回响（勾起回忆的老歌、旧时尚等）","en":"You can use a blast from the past as a light-hearted way of referring to something such as an old song or fashion that you hear or notice again, and which reminds you of an earlier time."},{"pos":"","cn":"","en":"相关词组：blast away blast off blast out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an enjoyable activity, especially something you do with other people, is pleasant and interesting","cn":""},{"en":"if something is fun , you enjoy it because it is very interesting and exciting","cn":""},{"en":"giving you a lot of pleasure, enjoyment and satisfaction","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 n v 4 ","senses":[{"en":"A blast is an explosion, or a sudden sharp noise. When you blast someone, you either shoot them, or hit them with a verbal explosion––a tirade of criticism."}]},"collocations":{"phrases":["ADJ. huge, powerful | bomb, nuclear, shotgun","BLAST + VERB hit sth, rip through sth, rock sth A huge bomb blast rocked central London last night.","PREP. in a/the ~ Twenty people were killed in the blast. 2 sudden rush of air/wind","ADJ. hot, icy She felt an icy blast of air.","PREP. ~ of a blast of cold air 3 sudden loud sound","ADJ. long | short | shrill","VERB + BLAST give","PREP. ~ on He gave a short blast on his trumpet."]},"media":{"uk":"media/ldoce/hwd/bre/3/blast_v0205.mp3","us":"media/ldoce/hwd/ame/7/blast1.mp3"},"examples":[{"en":"All the windows were blasted inwards with the force of the explosion.","cn":"爆炸的震动力把所有窗户都震碎到屋里。"},{"en":"The jumbo jet was blasted out of the sky.","cn":"那架巨型喷气式飞机在空中被炸成碎片。"}],"oxford":{"phon":"blɑːst","pos":"noun","senses":[{"en":"an explosion or a powerful movement of air caused by an explosion","cn":"爆炸；（爆炸引起的）气浪，冲击波","g":"[countable]","sc":"explosion","ex":{"en":"a bomb blast","cn":"炸弹爆炸"}},{"en":"a sudden strong movement of air","cn":"突如其来的强劲气流","g":"[countable]","sc":"of air","ex":{"en":"A blast of hot air hit us as we stepped off the plane.","cn":"我们下飞机时，一股热浪向我们袭来。"}},{"en":"a sudden loud noise, especially one made by a musical instrument that you blow, or by a whistle or a car horn","cn":"（吹奏乐器、哨子或汽车喇叭等突然发出的）响声，吹奏声，轰鸣","g":"[countable]","sc":"loud noise","ex":{"en":"three short blasts on the ship’s siren","cn":"船上三次短促的汽笛声"}},{"en":"strong criticism","cn":"严厉的批评；斥责；谴责","g":"[countable]","sc":"criticism","ex":{"en":"Blast for prison governors in judge’s report.","cn":"法官报告中对典狱长猛烈抨击"}},{"en":"a very happy experience that is a lot of fun","cn":"热闹的聚会；狂欢","g":"[singular]","lab":"informal","sc":"fun","ex":{"en":"The party was a blast.","cn":"聚会非常热闹。"}},{"en":"a piece of advertising or information that is sent to a large number of people at the same time by email","cn":"群发的电子邮件广告（或信息）","g":"[countable]","lab":"North American English, informal，，","sc":"email","ex":{"en":"They sent out email blasts and posted information on all their websites.","cn":"他们发送大量电子邮件并在所有网站上发布信息。"}},{"en":"to violently destroy or break something into pieces, using explosives","cn":"（用炸药）炸毁，把…炸成碎片；爆破","g":"[transitive, intransitive]","sc":"explode","ex":{"en":"They blasted a huge crater in the runway.","cn":"他们在飞机跑道上炸了一个大坑。"},"pos":"verb"},{"en":"to make a loud unpleasant noise, especially music","cn":"发出刺耳的高音，轰鸣（尤指音乐）","g":"[intransitive, transitive]","sc":"make loud noise","ex":{"en":"Music suddenly blasted out from the speakers.","cn":"喇叭中突然响起了轰鸣的音乐。"},"pos":"verb"},{"en":"to criticize somebody/something severely","cn":"严厉批评；猛烈抨击","g":"[transitive]","lab":"informal","sc":"criticize","ex":{"en":"The movie was blasted by all the critics.","cn":"这部影片受到了所有评论家的严厉抨击。"},"pos":"verb"},{"en":"to hit, kick or shoot somebody/something with a lot of force","cn":"狠打；猛踢；猛击","g":"[transitive]","lab":"informal","sc":"hit/kick/shoot","ex":{"en":"He blasted the ball past the goalie.","cn":"他飞脚将球踢过了守门员。"},"pos":"verb"},{"en":"to direct air, water, etc. at somebody/something with a lot of force","cn":"向…猛吹；（用水）向…喷射","g":"[transitive]","sc":"air/water","ex":{"en":"Police blasted the demonstrators with water cannons.","cn":"警察用高压水炮喷射示威者。"},"pos":"verb"},{"en":"to destroy something such as a plant with disease, cold, heat, etc.","cn":"使（植物等）毁于疾病（或寒冷、酷热等）","g":"[transitive, usually passive]","sc":"destroy with disease, etc.","ex":{"en":"Their whole crop had been blasted by a late frost.","cn":"一场晚霜把他们的庄稼全毁了。"},"pos":"verb"},{"en":"people sometimes say Blast! when they are annoyed about something","cn":"（恼怒时说）该死，倒霉","ex":{"en":"Oh blast! The car won't start.","cn":"真该死！车子发动不了。"},"pos":"exclamation"}]}},"blush":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（由于羞愧或难为情而）脸红，涨红了脸","en":"When you blush, your face becomes redder than usual because you are ashamed or embarrassed.","ex":{"en":"'Hello, Maria,' he said, and she blushed again","cn":"“你好，玛丽亚，”他说，这让她脸上又泛起了红晕。"}},{"pos":"PHRASE 短语","cn":"不让…尴尬；避免使…难为情","en":"If you spare someone's blushes or save someone's blushes, you avoid doing or saying something that will embarrass them.","ex":{"en":"'We don't want to name the man to spare his blushes,' said a police spokesman.","cn":"“为了不让当事人颜面扫地，我们就不指名道姓了，”一位警方发言人说道。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you blush or turn red , your face becomes red because you are embarrassed","cn":""},{"en":"to become red in the face, usually because you are embarrassed 〔","cn":"通常因难为情而〕脸红"},{"en":"to feel ashamed or embarrassed about something","cn":"感到羞愧[尴尬]"}]},"vocab":{"pos":"v n","senses":[{"en":"When you blush , you turn red because you are embarrassed. And, oddly enough, women wear the make-up variety of blush to add color to their cheeks — not to appear embarrassed but to appear attractive."}]},"collocations":{"phrases":["ADV. deeply, furiously, hotly | faintly, a little, slightly | readily She blushed more readily when she was a teenager. | angrily, guiltily","VERB + BLUSH make sb Stop teasing him?you're making him blush.","PREP. at He blushed at the mention of her name. | with She blushed crimson with embarrassment.","PHRASES blush crimson/scarlet"]},"media":{"uk":"media/ldoce/hwd/bre/2/blush_v0205.mp3","us":"media/ldoce/hwd/ame/5/blush1.mp3"},"examples":[{"en":"I blush to admit it, but I quite like her music.","cn":"不好意思，但我得承认我很喜欢她的音乐。"},{"en":"She blushed furiously at the memory of the conversation.","cn":"她一想起那次谈话就气得满脸通红。"}],"oxford":{"phon":"blʌʃ","pos":"verb","senses":[{"en":"to become red in the face because you are embarrassed or ashamed","cn":"（因尴尬或害羞）脸红，涨红了脸","g":"[intransitive]","ex":{"en":"to blush with embarrassment/shame","cn":"尴尬／羞愧得面颊绯红"}},{"en":"to be ashamed or embarrassed about something","cn":"（因某事）羞愧，尴尬","g":"[transitive]","ex":{"en":"I blush to admit it, but I quite like her music.","cn":"不好意思，但我得承认我很喜欢她的音乐。"}},{"en":"the red colour that spreads over your face when you are embarrassed or ashamed","cn":"（因难堪、羞愧）面部泛起的红晕","g":"[countable]","ex":{"en":"She felt a warm blush rise to her cheeks.","cn":"她感到双颊热辣辣的。"},"pos":"noun"},{"en":"a coloured cream or powder that some people put on their cheeks (= on their faces below the eyes) to give them more colour","cn":"腮红","g":"[uncountable, countable]","lab":"North American English","pos":"noun"}]}},"bleeding":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"该死的；讨厌的","en":"Bleeding is used by some people to emphasize what they are saying, especially when they feel strongly about something or dislike something."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the condition of losing blood from your body","cn":"流血﹐失血"},{"en":"→ haemorrhage : Use pressure to control the bleeding .","cn":"用力压住伤口止血。 The bleeding had almost stopped . 血基本上已经止住了。 He died of internal bleeding . 他死于内出血。 severe/heavy bleeding (= w"},{"en":"an offensive way of emphasizing something when you are angry","cn":"讨厌的﹐他妈的﹐该死的"}]},"collocations":{"phrases":["ADJ. heavy, massive | uncontrollable | internal","VERB + BLEEDING have, suffer from | cause | control, staunch, stem, stop","PREP. ~ from Some drugs can cause bleeding from the small intestine."]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdebleeding.mp3","us":"media/ldoce/hwd/ame/b/laadbleeding.mp3"},"examples":[{"en":"Press firmly on the wound to stop the bleeding.","cn":"用力压住伤口止血。"},{"en":"Get your bleeding hands off my car!","cn":"拿开你的臭手﹐不要碰我的汽车！"}],"oxford":{"phon":"ˈbliːdɪŋ","pos":"adjective","senses":[{"en":"a swear word that many people find offensive that is used to emphasize a comment or an angry statement","cn":"（加强语气）该死的，他妈的"},{"en":"the process of losing blood from the body","cn":"流血；失血","ex":{"en":"Press firmly on the wound to stop the bleeding.","cn":"用力压住伤口止血。"},"pos":"noun"}]},"base":"bleed"},"bloc":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"国家集团；阵营；共同体","en":"A bloc is a group of countries which have similar political aims and interests and that act together over some issues.","ex":{"en":"...the former Soviet bloc.","cn":"前苏联集团"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large group of people or countries with the same political aims, working together","cn":"集团﹐阵营"}]},"collocations":{"phrases":["ADJ. large, solid, substantial A solid bloc of union members support the decision. | economic, military, trading | Communist, Eastern, Sovie","PREP. in/within a/the ~ There have been growing tensions within the trading bloc.","PHRASES en bloc (= all together; all at the same time)"]},"media":{"uk":"media/ldoce/hwd/bre/8/bloc0205.mp3","us":"media/ldoce/hwd/ame/b/bloc1.mp3"},"examples":[{"en":"the former Soviet bloc","cn":"苏联阵营"}],"oxford":{"phon":"blɒk","pos":"noun","senses":[{"en":"a group of countries that work closely together because they have similar political interests","cn":"（政治利益一致的）国家集团","lab":"US English","ex":{"en":"Eastern bloc countries","cn":"东欧集团国家"}}]}},"blouse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宽松的女短衫；女式衬衫","en":"A blouse is a kind of shirt worn by a girl or woman."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a shirt for women","cn":"女式宽松短衫﹐女衬衫"}]},"collocations":{"phrases":["ADJ. long-sleeved, short-sleeved, sleeveless | high-necked | cotton, silk, etc. | embroidered, frilled, frilly | see-through | school","VERB + BLOUSE have on, wear | put on | button up, unbutton | take off"]},"media":{"uk":"media/ldoce/hwd/bre/0/blouse0205.mp3","us":"media/ldoce/hwd/ame/1/blouse.mp3"},"examples":[{"en":"a silk blouse","cn":"丝质女衬衫"}],"oxford":{"phon":"blaʊz","pos":"noun","senses":[{"en":"a piece of clothing like a shirt, worn by women","cn":"（女式）短上衣，衬衫"}]}},"blockade":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"封锁；阻塞","en":"A blockade of a place is an action that is taken to prevent goods or people from entering or leaving it.","ex":{"en":"Striking lorry drivers agreed to lift their blockades of main roads","cn":"罢工的卡车司机们同意解除对主干道的封堵。"}},{"pos":"VERB 动词","cn":"阻塞；封锁","en":"If a group of people blockade a place, they stop goods or people from reaching that place. If they blockade a road or a port, they stop people using that road or port.","ex":{"en":"Truck drivers have blockaded roads to show their anger over new driving regulations","cn":"卡车司机通过阻塞道路来表达他们对新机动车交通法规的不满。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the surrounding of an area by soldiers or ships to stop people or supplies entering or leaving 〔","cn":"对某地的〕封锁"},{"en":"something that is used to stop vehicles or people entering or leaving a place","cn":"堵塞物﹐障碍物"},{"en":"if someone or something is in the way , they are in a position that stops you from going where you want","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A blockade is an obstacle that stands between you and something you're trying to reach. After a robbery, police might set up a blockade around the neighborhood to catch the thief."}]},"collocations":{"phrases":["ADJ. complete, total | tight | partial | virtual | economic, military, naval","VERB + BLOCKADE impose | end, lift, remove | enforce, maintain | tighten | ease, relax | break, get through, run They attempted to break the","PREP. ~ against the need to enforce a naval blockade against the country | ~ around/round a blockade around the city | ~ by the blockade by "]},"media":{"uk":"media/ldoce/hwd/bre/c/blockade_n0205.mp3","us":"media/ldoce/hwd/ame/9/l3blockade.mp3"},"examples":[{"en":"The police set up blockades on highways leading out of the city.","cn":"警察在出城的公路上设了路障。"},{"en":"an economic blockade (= stopping goods from entering or leaving a country)","cn":"经济封锁"}],"oxford":{"phon":"blɒˈkeɪd","pos":"noun","senses":[{"en":"the action of surrounding or closing a place, especially a port, in order to stop people or goods from coming in or out","cn":"（尤指对港口的）包围，封锁","ex":{"en":"a naval blockade","cn":"海上封锁"}},{"en":"a barrier that stops people or vehicles from entering or leaving a place","cn":"障碍物；屏障","ex":{"en":"The police set up blockades on highways leading out of the city.","cn":"警察在出城的公路上设了路障。"}},{"en":"to surround a place, especially a port, in order to stop people or goods from coming in or out","cn":"包围，封锁（尤指港口）","ex":{"en":"All the ports had been blockaded.","cn":"所有港口都被封锁了。"},"pos":"verb"}]}},"blitz":{"collins":{"senses":[{"pos":"VERB 动词","cn":"以闪电战空袭；以闪电战攻击","en":"If a city or building is blitzed during a war, it is attacked by bombs dropped by enemy aircraft.","ex":{"en":"In the autumn of 1940 London was blitzed by an average of two hundred aircraft a night","cn":"1940年秋，伦敦平均每晚遭到200架飞机的空袭。"}},{"pos":"N-PROPER 专有名词","cn":"德军对英国城市的空袭，伦敦大轰炸（1940年至1941年间）","en":"The heavy bombing of British cities by German aircraft in 1940 and 1941 is referred to as the Blitz."},{"pos":"N-COUNT 可数名词","cn":"努力；下工夫","en":"If you have a blitz on something, you make a big effort to deal with it or to improve it.","ex":{"en":"Regional accents are still acceptable but there is to be a blitz on incorrect grammar.","cn":"地方口音还可以接受，但要下大力气纠正语法错误。"}},{"pos":"N-COUNT 可数名词","cn":"（为吸引注意力的）大规模活动","en":"An advertising or publicity blitz is a major effort to make the public aware of something.","ex":{"en":"On December 8 the media blitz began in earnest.","cn":"12月8日，一场大规模媒体宣传活动轰轰烈烈地展开了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden military attack, especially from the air","cn":"闪电般的猛烈袭击〔尤指空袭〕﹔闪电战"},{"en":"a period of great effort in order to deal with something quickly and completely","cn":"闪电行动"},{"en":"a big effort to make people notice something or buy something 〔","cn":"为吸引注意力或吸引人们购买某物的〕大规模行动"}]},"vocab":{"pos":"n v","senses":[{"en":"A sudden, overwhelming military attack during war is a blitz . Sometimes a major blitz can lead to the end of a conflict."}]},"collocations":{"phrases":["ADJ. bombing | wartime","VERB + BLITZ carry out","PREP. during/in a/the ~ Many people died in the London blitz. | ~ on Enemy bombers carried out a blitz on the city. 2 campaign; sudden, grea","ADJ. marketing, media, sales","VERB + BLITZ have, launch, mount We decided to have a blitz on the kitchen (= to clean the kitchen thoroughly) .","PREP. ~ on a blitz on illegal parking"]},"media":{"uk":"media/ldoce/hwd/bre/5/blitz0205.mp3","us":"media/ldoce/hwd/ame/a/blitz1.mp3"},"examples":[{"en":"Five shops were damaged in a firebomb blitz.","cn":"在一次燃烧弹袭击中有五家店铺被烧毁。"},{"en":"an advertising/a media blitz (= a lot of information about sth on television, in newspapers, etc.)","cn":"集中火力的广告/媒体宣传"}],"oxford":{"phon":"blɪts","pos":"noun","senses":[{"en":"a sudden attack","cn":"突袭；闪电战","g":"[countable, usually singular]","ex":{"en":"Five shops were damaged in a firebomb blitz.","cn":"在一次燃烧弹袭击中有五家店铺被烧毁。"}},{"en":"the German air attacks on the United Kingdom in 1940–1","cn":"1940 至 1941 年德国对英国的空袭","g":"[singular]","ex":{"en":"Many people died in the London Blitz.","cn":"许多人在伦敦大空袭中丧生。"}},{"en":"a sudden organized effort to deal with something or achieve something","cn":"突然的行动；突袭","g":"[countable, usually singular]","lab":"informal","ex":{"en":"a blitz on passengers who avoid paying fares","cn":"对逃票乘客的突击检查"}},{"en":"to attack or damage a city by dropping a large number of bombs on it in a short time","cn":"用闪电战空袭（或毁坏）","g":"[transitive]","ex":{"en":"London was heavily blitzed in the war.","cn":"伦敦在战争中遭受重创。"},"pos":"verb"},{"en":"(of food) to mix or cut into smaller pieces using an electric mixing machine","cn":"（用电动搅拌机将食物）搅拌，打碎","g":"[transitive, intransitive]","ex":{"en":"Blitz the strawberries to a purée in a food processor.","cn":"用食物加工机将草莓打成酱。"},"pos":"verb"}]}},"bladder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"膀胱","en":"Your bladder is the part of your body where urine is stored until it leaves your body."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the organ in your body that holds urine (= waste liquid ) until it is passed out of your body","cn":"膀胱"},{"en":"a bag of skin, leather, or rubber, for example inside a football, that can be filled with air or liquid 〔","cn":"可充气或充水的〕皮囊﹐气囊〔如足球的内胆〕"}]},"collocations":{"phrases":["ADJ. full | irritable, weak","VERB + BLADDER empty","BLADDER + NOUN control | cancer, infection, problem He died of bladder cancer."]},"media":{"uk":"media/ldoce/hwd/bre/b/bladder0205.mp3","us":"media/ldoce/hwd/ame/2/bladder.mp3"},"oxford":{"phon":"ˈblædə(r)","pos":"noun","senses":[{"en":"an organ that has the shape of a bag in which liquid waste (= urine) collects before it is passed out of the body","cn":"膀胱","ex":{"en":"He died of bladder cancer.","cn":"他死于膀胱癌。"}},{"en":"a bag made of rubber, leather, etc. that can be filled with air or liquid, such as the one inside a football","cn":"皮囊，气囊（如球胆）"}]}},"blameless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无可责备的；没有过错的；清白的","en":"Someone who is blameless has not done anything wrong.","ex":{"en":"He feels he is blameless","cn":"他觉得自己并没有什么过失。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone is innocent of a crime, they did not do it - use this especially about someone that other people think is guilty","cn":""},{"en":"if someone is not guilty of a crime, they did not do it - use this especially when a court has officially decided that someone did not do a crime","cn":""},{"en":"not having done anything wrong, or not responsible for something bad that has happened","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. quite (= totally) She herself was quite blameless. | far from, not entirely Johnson himself was far from blameless."]},"media":{"uk":"media/ldoce/hwd/bre/9/blameless0205.mp3","us":"media/ldoce/hwd/ame/9/blameless.mp3"},"examples":[{"en":"None of us is entirely blameless in this matter.","cn":"在这件事上我们没有一个人是完全没有责任的。"},{"en":"to lead a blameless life","cn":"活得清白"}],"oxford":{"phon":"ˈbleɪmləs","pos":"adjective","senses":[{"en":"doing no wrong; free from responsibility for doing something bad","cn":"无过错的；无可指责的","ex":{"en":"to lead a blameless life","cn":"活得清白"}}]}},"blanket":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"毯子；毛毯","en":"A blanket is a large square or rectangular piece of thick cloth, especially one which you put on a bed to keep you warm."},{"pos":"N-COUNT 可数名词","cn":"覆盖层","en":"A blanket of something such as snow is a continuous layer of it which hides what is below or beyond it.","ex":{"en":"The mud disappeared under a blanket of snow","cn":"泥巴被积雪盖住了。"}},{"pos":"N-SING 单数名词","cn":"（不好的情感、性质等的）弥漫，充斥","en":"You can refer to something such as an unpleasant emotion or an undesirable quality that seems to affect every aspect of a particular situation as a blanket of that emotion or quality.","ex":{"en":"It seems as if the blanket of depression is in some way necessary to help them blot out the even greater pain of real life","cn":"似乎这种弥漫的抑郁情绪多少能帮助他们忘却一些现实生活中更大的痛苦。"}},{"pos":"VERB 动词","cn":"覆盖；遮盖；盖住","en":"If something such as snow blankets an area, it covers it.","ex":{"en":"More than a foot of snow blanketed parts of Michigan","cn":"密歇根州的部分地区被超过一英尺厚的积雪所覆盖。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"通用的；全面的；无一例外的","en":"You use blanket to describe something when you want to emphasize that it affects or refers to every person or thing in a group, without any exceptions.","ex":{"en":"There's already a blanket ban on foreign unskilled labour in Japan.","cn":"日本已经全面禁止国外非熟练工入境。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cover for a bed, usually made of wool","cn":"毯子﹐毛毯"},{"en":"a thick covering or area of something","cn":"厚（的覆盖）层"},{"en":"something that makes it hard for you to find information or the truth about something 〔","cn":"使信息或真相难以被发现的〕蒙蔽之物"}]},"collocations":{"phrases":["ADJ. heavy, thick | thin | warm | electric","VERB + BLANKET cover sb with, wrap sb in | draw up, pull up She pulled the blanket up and went to sleep. | kick off, push off, throw off","PREP. beneath/under a/the ~ They shivered under their thin blankets."]},"media":{"uk":"media/ldoce/hwd/bre/8/blanket_adj0205.mp3","us":"media/ldoce/hwd/ame/3/blanket1.mp3"},"examples":[{"en":"Snow soon blanketed the frozen ground.","cn":"冻土上很快就形成了一层厚厚的积雪。"},{"en":"( figurative ) The trial was conducted under a blanket of secrecy.","cn":"审讯在高度保密下进行。"}],"oxford":{"phon":"ˈblæŋkɪt","pos":"noun","senses":[{"en":"a large cover, often made of wool, used especially on beds to keep people warm","cn":"毯子；毛毯","ex":{"en":"It’s cold tonight—can I have another blanket?","cn":"今晚很冷，能再给我一条毯子吗？"}},{"en":"a thick layer or mass of something","cn":"厚层；厚的覆盖层","g":"[usually singular]","lab":"figurative","ex":{"en":"a blanket of fog/snow/cloud","cn":"厚厚的一层雾／雪／云"}},{"en":"including or affecting all possible cases, situations or people","cn":"包括所有情形（或人员）的；总括的；综合的","ex":{"en":"a blanket ban on tobacco advertising","cn":"烟草广告的全面取缔"},"pos":"adjective"},{"en":"to cover something completely with a thick layer","cn":"以厚层覆盖","ex":{"en":"The ground was soon blanketed with snow.","cn":"地面很快铺上了一层厚厚的积雪。"},"pos":"verb"}]}},"blueprint":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蓝图；计划；设想；构想","en":"A blueprint for something is a plan or set of proposals that shows how it is expected to work.","ex":{"en":"The country's president will offer delegates his blueprint for the country's future.","cn":"该国总统会向代表们展示他构想的国家未来发展的蓝图。"}},{"pos":"N-COUNT 可数名词","cn":"（建筑、设计的）蓝图","en":"A blueprint of an architect's building plans or a designer's pattern is a photographic print consisting of white lines on a blue background. Blueprints contain all of the information that is needed to build or make something.","ex":{"en":"...a blueprint of the whole place, complete with heating ducts and wiring","cn":"整个地方的规划图，包括暖气管和布线"}},{"pos":"N-COUNT 可数名词","cn":"（基因）模型，型板","en":"A genetic blueprint is a pattern which is contained within all living cells. This pattern decides how the organism develops and what it looks like.","ex":{"en":"The offspring contain a mixture of the genetic blueprint of each parent","cn":"子女身上遗传了父母双方的基因型板。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you have decided to do, and the methods you will use to do it","cn":""},{"en":"a detailed plan explaining exactly how to achieve something","cn":""},{"en":"a carefully designed plan for achieving something that is difficult and may take a long time","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A blueprint is a guide for making something — it's a design or pattern that can be followed. Want to build the best tree house ever? Draw up a blueprint and follow the design carefully."}]},"collocations":{"phrases":["ADJ. new | final | economic, personal","VERB + BLUEPRINT have The government does not have a blueprint for reform. | create, develop, draw up | act as, form, provide, serve as The ","PREP. for a blueprint for change"]},"media":{"uk":"media/ldoce/hwd/bre/3/blueprint0205.mp3","us":"media/ldoce/hwd/ame/f/blueprint.mp3"},"examples":[{"en":"DNA carries the genetic blueprint which tells any organism how to build itself.","cn":"脱氧核糖核酸带有表明有机体形成方式的遗传型板。"},{"en":"a blueprint for the privatization of health care","cn":"保健私有化方案"}],"oxford":{"phon":"ˈbluːprɪnt","pos":"noun","senses":[{"en":"a photographic print of a plan for a building or a machine, with white lines on a blue background","cn":"（建筑、机器等的）蓝图","ex":{"en":"blueprints of a new aircraft","cn":"新型飞机的蓝图"}},{"en":"a plan which shows what can be achieved and how it can be achieved","cn":"行动方案；计划蓝图","ex":{"en":"a blueprint for the privatization of healthcare","cn":"医疗保健私有化方案"}},{"en":"the pattern in every living cell, which decides how the plant, animal or person will develop and what it will look like","cn":"（生物细胞的）模型，型板","lab":"specialist","ex":{"en":"DNA carries the genetic blueprint which tells any organism how to build itself.","cn":"脱氧核糖核酸带有决定有机体形成方式的遗传型板。"}}]}},"blaze":{"collins":{"senses":[{"pos":"VERB 动词","cn":"熊熊燃烧","en":"When a fire blazes, it burns strongly and brightly.","ex":{"en":"Three people died as wreckage blazed, and rescuers fought to release trapped drivers","cn":"汽车残骸熊熊燃烧，三人葬身火海，救援人员奋力解救被困的司机们。"}},{"pos":"N-COUNT 可数名词","cn":"大火；烈火","en":"A blaze is a large fire which is difficult to control and which destroys a lot of things.","ex":{"en":"Two firemen were hurt in a blaze which swept through a tower block last night.","cn":"昨晚，一场大火吞噬了一座高层建筑，两位消防员被烧伤。"}},{"pos":"VERB 动词","cn":"照耀；发出（强光）；绽放（光彩）","en":"If something blazes with light or colour, it is extremely bright.","ex":{"en":"The gardens blazed with colour.","cn":"花园色彩绚丽。"}},{"pos":"VERB 动词","cn":"（眼睛）闪耀，闪烁，充满（感情）；（情感在眼中）燃烧","en":"If someone's eyes are blazing with an emotion, or if an emotion is blazing in their eyes, their eyes look very bright because they are feeling that emotion so strongly.","ex":{"en":"He got to his feet and his dark eyes were blazing with anger","cn":"他站起身来，乌黑的眼睛里喷射着怒火。"}},{"pos":"N-SING 单数名词","cn":"大量（宣传或关注）","en":"A blaze of publicity or attention is a great amount of it.","ex":{"en":"He was arrested in a blaze of publicity.","cn":"他在铺天盖地的报道中被捕了。"}},{"pos":"VERB 动词","cn":"（枪炮）连续射击（或开火）","en":"If guns blaze, or blaze away, they fire continuously, making a lot of noise.","ex":{"en":"Guns were blazing, flares going up and the sky was lit up all around","cn":"炮火不断，信号弹此起彼伏，四周的天空都被照亮了。"}},{"pos":"","cn":"","en":"with all guns blazing→see: ;"},{"pos":"PHRASE 短语","cn":"开辟道路；作开路先锋","en":"If someone blazes a trail, they discover or develop something new.","ex":{"en":"These surgeons have blazed the trail in the treatment of bomb victims.","cn":"这些外科医生在治疗炸伤方面开辟了新的道路。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"flames that burn in an uncontrolled way and destroy or damage things","cn":""},{"en":"the bright parts of a fire that you see burning in the air","cn":""},{"en":"a large and dangerous fire – used especially in news reports","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 n","senses":[{"en":"A blaze is a bright, strong flame. A raging fire is blazing and you can also say other types of shining, like with talent, are types of blazing ."}]},"collocations":{"phrases":["ADJ. fierce, intense, massive","VERB + BLAZE attend, fight, tackle The fire brigade attended the blaze. | control, bring/get under control | extinguish, put out | fan Stron","BLAZE + VERB spread, sweep through sth The blaze swept through the whole building.","PREP. in a/the ~ The antiques were destroyed in a blaze last year."]},"media":{"uk":"media/ldoce/hwd/bre/8/blaze_v0205.mp3","us":"media/ldoce/hwd/ame/a/blaze1.mp3"},"examples":[{"en":"The department is blazing a trail in the field of laser surgery.","cn":"这个部门正在为激光外科学领域开辟一条新路。"},{"en":"The sun blazed down from a clear blue sky.","cn":"耀眼的阳光从清澈蔚蓝的天空中照射下来。"}],"oxford":{"phon":"bleɪz","pos":"verb","senses":[{"en":"to burn brightly and strongly","cn":"熊熊燃烧","g":"[intransitive]","ex":{"en":"A huge fire was blazing in the fireplace.","cn":"壁炉中火烧得正旺。"}},{"en":"to shine brightly","cn":"闪耀；发亮光","g":"[intransitive]","ex":{"en":"The sun blazed down from a clear blue sky.","cn":"耀眼的阳光从清澈蔚蓝的天空中照射下来。"}},{"en":"if somebody’s eyes blaze, they look extremely angry","cn":"怒视；（怒火）燃烧","g":"[intransitive]","lab":"formal","ex":{"en":"Her eyes were blazing with fury.","cn":"她的双眼燃烧着怒火。"}},{"en":"to make news or information widely known by telling people about it in a way they are sure to notice","cn":"大肆宣扬","g":"[transitive, usually passive]","ex":{"en":"The story was blazed all over the daily papers.","cn":"那个传闻被各家报纸炒得沸沸扬扬。"}},{"en":"if a gun or somebody using a gun blazes, the gun fires continuously","cn":"连续射击","g":"[intransitive]","ex":{"en":"In the distance machine guns were blazing.","cn":"机关枪在远处不停地射击。"}},{"en":"a very large fire, especially a dangerous one","cn":"烈火；火灾","g":"[countable]","ex":{"en":"Five people died in the blaze.","cn":"火灾中有五人丧生。"},"pos":"noun"},{"en":"strong bright flames in a fire","cn":"火焰","g":"[singular]","ex":{"en":"Dry wood makes a good blaze.","cn":"干木柴烧得旺。"},"pos":"noun"},{"en":"a very bright show of lights or colour; a show of something that is impressive or likely to attract attention","cn":"（光或色彩等的）展现","g":"[singular]","ex":{"en":"The gardens are a blaze of colour.","cn":"花园里姹紫嫣红。"},"pos":"noun"},{"en":"a sudden show of very strong feeling","cn":"（强烈感情的）迸发；发泄","g":"[singular]","ex":{"en":"a blaze of anger/passion/hate","cn":"怒火／激情／仇恨的迸发"},"pos":"noun"},{"en":"a white mark on an animal’s face","cn":"动物面部的白斑","g":"[countable, usually singular]","pos":"noun"}]}}});
